/**
 * AP English Literature — Exit Quiz Question Pool
 * Lesson-aligned items for every routed topic (15+ per topic, 2+ per lesson
 * part, each tagged with the teaching `part`). Feeds topic exit quizzes, the
 * course diagnostic (by domain), unit tests (by domain), and the daily question.
 */

import { relevantPool } from './relevance-fallback'
import { shuffleArray } from '@/lib/shuffle-options'
export interface EngLitQuestion {
  question: string
  options: string[]
  correctAnswer: number
  explanation: string
  difficulty: 'easy' | 'medium' | 'hard'
  domain: string
  topicSlug: string
  formSet: number
  /** Lesson part (1–7) that teaches this item; a failed exit quiz routes back to it. */
  part?: number
}

export const engLitQuestionPool: EngLitQuestion[] = [
  // ── Domain: short-fiction ───────────────────────────────
  // englit-short-fiction-1
  { question: 'A 2,000-word story spends a full paragraph on a cracked teacup that the mother refuses to throw away. Applying the principle of compression, how should a reader treat this detail?', options: ['As realistic texture that matters much less than the plot\'s events', 'As a coded symbol with one fixed meaning the reader must find', 'As background included mainly to establish the time period', 'As likely purposeful, carrying meaning beyond its literal role'], correctAnswer: 3, explanation: 'Compression means a short story\'s details are densely purposeful, so a detail given this much space likely carries interpretive weight. Treating it as mere texture or period background ignores that density, and reducing it to one fixed code overlooks that a detail\'s meaning comes from its context in the story.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'Read the passage: “When the waiter brought the wrong soup, Mr. Hale said nothing, ate it slowly, and left a larger tip than usual.” What does this brief moment most likely reveal about Mr. Hale?', options: ['His generosity reflects a recent stroke of good luck', 'He avoids conflict even when doing so costs him something', 'He secretly enjoys trying food he did not order', 'He is too distracted to notice what he is eating'], correctAnswer: 1, explanation: 'Short fiction often reveals character through small choices under mild pressure: Mr. Hale accepts a mistake silently and even rewards it, which suggests he avoids confrontation at his own expense. Nothing in the passage mentions good luck or enjoyment, and eating the soup slowly suggests he noticed it rather than that he was distracted.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'A story follows a boy\'s eager preparations for his father\'s visit. The final sentences say he set the table for two and, after dark, quietly cleared one plate. How does this ending most affect the earlier scenes?', options: ['It resolves the conflict by confirming that the father arrived late', 'It shifts attention to a new conflict unrelated to the preparations', 'It recasts the boy\'s preparations as poignant, not merely cheerful', 'It shows the preparations were meant mainly as the story\'s humor'], correctAnswer: 2, explanation: 'An ending effect often reframes what came before: the cleared plate implies the father never came, so the boy\'s eagerness becomes painful in hindsight. The ending does not show a late arrival, it extends rather than abandons the central situation, and nothing in it treats the preparations as comic.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'A short story about a daughter at her mother\'s funeral is told in flat, clipped sentences: she notes the brass casket handles and the time on the wall clock, never names a feeling, and afterward sits in her parked car for an hour. Which thesis would earn the most credit in an AP prose fiction essay?', options: ['Her clipped, factual account of the funeral exposes a grief that the daughter cannot yet admit.', 'The narrator\'s flat, clipped account of the funeral reveals that she feels relief rather than loss.', 'The brass casket handles symbolize the family\'s wealth and its concern for appearances.', 'The story follows a daughter through her mother\'s funeral, from the service to the drive home.'], correctAnswer: 0, explanation: 'The strongest thesis links a technique to meaning and accounts for the details: the flat style, together with the hour spent in the parked car, suggests grief held back. Reading the flatness as relief ignores that hour, the brass handles are a passing detail with no evidence of wealth or vanity, and tracing the day\'s events is summary rather than an arguable claim.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'Which of the following is an example of indirect characterization?', options: ['The narrator states plainly that the character is unusually honest', 'The narrator opens by giving the character\'s age, job, and hometown', 'A character returns a lost wallet without checking inside it', 'The story\'s title names the character and describes her as honest'], correctAnswer: 2, explanation: 'Indirect characterization lets readers infer traits from actions, speech, or thoughts, as when returning a wallet unopened implies honesty. A narrator\'s plain statement of a trait or a title that labels the character is direct characterization, and basic facts such as age or job do not reveal a trait at all.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'A story is set in a company town where the mill owns every house, store, and church. Which claim best explains how this setting works in the story?', options: ['It narrows the workers\' options, so compliance reads as pressure and not weakness', 'It offers a realistic backdrop that stays separate from the characters\' decisions', 'It mainly establishes the historical period so readers can date the events', 'It creates a cheerful mood that contrasts with the quarrels among the workers'], correctAnswer: 0, explanation: 'Setting includes social and economic conditions that constrain or enable choices; a town owned by one employer limits what workers can do, which changes how readers judge their compliance. Treating the setting as a detached backdrop or a dating device misses that pressure, and nothing about total ownership suggests a cheerful mood.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'Read the passage: “The kitchen was scrubbed so clean that the linoleum had worn through in pale ovals by the sink. When her sister set a purse on a chair, Martha moved it to the hook by the door before pouring the coffee.” What does the passage most suggest about Martha?', options: ['She is preparing the house to be shown to possible new buyers', 'She resents her sister for arriving at the house without warning', 'She is too poor to replace the old floor she cleans so carefully', 'Her need for order governs even small courtesies toward a guest'], correctAnswer: 3, explanation: 'The worn ovals show years of scrubbing, and moving the purse before serving coffee shows that order comes before hospitality; both details build one consistent trait. The passage gives no evidence of a sale or of resentment, and although the floor is worn, the passage stresses the scrubbing that wore it rather than any lack of money.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'In Story A, a narrator describes a farmhouse in loving, sensory detail as she prepares to leave it; in Story B, a narrator describes a nearly identical farmhouse as a flat list of needed repairs. What best explains the different effects of the two descriptions?', options: ['Story A\'s farmhouse is worth more, so it naturally receives more description', 'The selected images and diction reveal each narrator\'s attitude toward the place', 'Story B\'s narrator is more reliable, since lists are more objective than images', 'The houses belong to different eras, and the era accounts for each tone'], correctAnswer: 1, explanation: 'When two narrators describe similar settings differently, the selection of details and the connotations of words reveal their attitudes, here attachment versus detachment. The houses are nearly identical, so value or era cannot explain the contrast, and a list of repairs is still a selective, attitude-laden account rather than proof of greater reliability.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'In a story where a blizzard traps two estranged brothers in a cabin for three days, the storm most likely functions to', options: ['force a confrontation the brothers have so far been able to avoid', 'replace the brothers\' quarrel with a natural enemy they fight together', 'establish the season so the story\'s timeline remains easy to follow', 'create a peaceful mood that the brothers\' bickering later disrupts'], correctAnswer: 0, explanation: 'Setting often creates the conditions for conflict; confinement removes the distance that let the estranged brothers avoid each other. The storm intensifies rather than replaces their conflict, its role is far larger than marking the season, and being trapped in a blizzard is a source of pressure, not peace.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'A minor character whose contrasting traits highlight the protagonist\'s qualities is best described as a', options: ['stock character', 'round character', 'foil character', 'static character'], correctAnswer: 2, explanation: 'A foil exists in contrast to another character, so the comparison sharpens our view of the protagonist. A stock character is a familiar type, a round character is complex and fully developed, and a static character simply does not change; none of these terms names the contrasting function.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'A character who undergoes an important internal change over the course of a story is best described as', options: ['a round character', 'a dynamic character', 'a flat character', 'a static character'], correctAnswer: 1, explanation: 'A dynamic character changes in values, understanding, or behavior over the narrative. A round character is complex but may not change, a flat character is defined by one or two traits, and a static character stays essentially the same.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'At the start of a story, a girl hides her grandmother\'s accented letters from her friends; at the end, she reads one aloud at the grandmother\'s funeral but stumbles over the words. Which reading best accounts for this development?', options: ['She has put her shame behind her, so the stumble simply reflects her grief', 'She remains as ashamed as before, and reading aloud is merely a social duty', 'She reads the letter mainly to impress the relatives who are watching her', 'Her change is real but incomplete, as the stumble shows old shame lingering'], correctAnswer: 3, explanation: 'Strong AP readings account for complexity: choosing to read the letter publicly marks growth, while the stumble suggests the earlier discomfort has not vanished. Claiming total transformation or no change at all ignores one of the two details, and the passage offers no evidence that she is performing for the relatives.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'A student claims, “The cramped apartment mirrors Ana\'s sense that her future is closing in.” Which detail from the story would best support this claim?', options: ['Ana\'s apartment is on the fourth floor of an older building downtown', 'Ana\'s mother calls every Sunday to ask how the new job is going', 'Ana sees that her only window now faces a new brick wall', 'Ana has been living in the city for a little more than six years'], correctAnswer: 2, explanation: 'Evidence must connect directly to the claim; a window newly blocked by a wall makes the space feel closed in and fits the idea of a narrowing future. The floor number and the length of her stay are neutral facts, and the mother\'s calls concern a different relationship rather than the apartment.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'A story includes the line “He polished his late father\'s boots every night, though he never wore them.” Which sentence offers the strongest commentary on this detail?', options: ['This detail uses imagery to show that the son polishes his father\'s boots every single night.', 'The nightly ritual keeps the father present yet shows the son is not ready to take his place.', 'This shows that the son is a very neat and careful person who likes his things kept clean.', 'The boots are a symbol, and symbols are among the most important devices in fiction.'], correctAnswer: 1, explanation: 'Commentary explains what evidence means; the strongest sentence interprets both the ritual and the refusal to wear the boots as unresolved grief and inheritance. Restating the detail adds no insight, reading it as general neatness ignores whose boots they are, and labeling a device without interpreting it is not commentary.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  { question: 'On the AP English Literature exam, the prose fiction essay asks students mainly to', options: ['analyze how an author\'s techniques convey meaning in a given passage', 'summarize the passage\'s plot and identify its historical background', 'argue whether the passage\'s characters made morally correct choices', 'compare the passage with a novel the student has studied in class'], correctAnswer: 0, explanation: 'The prose fiction question asks students to analyze how an author uses literary elements and techniques to convey a complex portrayal or meaning in the given passage. Summary and historical background are not the task, judging characters\' morality replaces analysis with opinion, and outside works belong to the literary argument essay rather than this one.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 1, part: 1 },
  { question: 'Which term names the time, place, and social conditions, including a community\'s values, in which a narrative unfolds?', options: ['mood', 'exposition', 'atmosphere', 'setting'], correctAnswer: 3, explanation: 'Setting covers when and where a story happens, including its social and cultural conditions. Mood is the feeling a work evokes in readers, exposition is the opening information that introduces a situation, and atmosphere is the emotional quality a place carries.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-1', formSet: 2, part: 1 },
  // englit-short-fiction-2
  { question: 'A fire station burns down because its own smoke detector was never installed. This outcome is an example of', options: ['dramatic irony', 'situational irony', 'verbal irony', 'understatement'], correctAnswer: 1, explanation: 'Situational irony is a gap between what we expect to happen and what actually happens; a fire station is the last place we expect to burn for lack of fire safety. Dramatic irony requires the audience to know something a character does not, verbal irony is a gap between what a speaker says and means, and understatement deliberately downplays something.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'Readers learn in the first paragraph that the letter Clara awaits was destroyed in a flood; the rest of the story shows her checking the mailbox each morning. What effect does this arrangement create?', options: ['Suspense about whether the letter will come drives the plot', 'Clara appears foolish, inviting readers to mock her persistence', 'The flood replaces Clara\'s waiting as the story\'s main conflict', 'Each hopeful walk out to the box becomes painful to watch'], correctAnswer: 3, explanation: 'This is dramatic irony: readers know what Clara does not, so her hope becomes poignant. There can be no suspense about the letter\'s arrival once readers know it was destroyed, nothing in the arrangement invites mockery, and the flood is background that intensifies her waiting rather than replacing it.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'A story about a factory strike is narrated by the owner\'s teenage son, who repeats his father\'s phrases about “troublemakers” and “ungrateful hands.” How does this perspective most shape the reader\'s judgment?', options: ['Readers accept the son\'s view because he witnesses the strike\'s events firsthand', 'Readers gain direct access to the strikers\' private thoughts through the son\'s eyes', 'Readers sense a gap between the son\'s borrowed views and the strikers\' real situation', 'Readers come to trust the son as an expert on the strike\'s economic causes'], correctAnswer: 2, explanation: 'Perspective filters what readers see and how they judge it; a narrator who parrots a parent\'s loaded language invites readers to question his account. Being present does not make his judgment sound, a first-person outsider cannot report the strikers\' inner thoughts, and nothing suggests he understands the economics.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'Read the passage: “We\'ll repaint the nursery,” he said, folding the tiny sweaters into a box and taping it shut twice. What is most strongly implied?', options: ['The couple has suffered a loss that they are not naming directly', 'Husband and wife are excited to redecorate for a new baby', 'The husband dislikes the color his wife chose for the room', 'The sweaters are being shipped to relatives who live abroad'], correctAnswer: 0, explanation: 'Implication lets readers infer meaning the text withholds: sealing away tiny sweaters, and taping the box twice, suggests grief and finality, so repainting signals erasing a nursery that will not be used. The packing is too somber for excitement, nothing concerns the paint color, and no relatives or shipping are mentioned.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'A character torn between loyalty to her family and her own ambition faces which kind of conflict?', options: ['a conflict between characters', 'a conflict within the self', 'a conflict with society', 'a conflict with nature'], correctAnswer: 1, explanation: 'A struggle between competing desires or values inside one person is an internal conflict. A conflict between characters would require an opposing person, a conflict with society would pit her against social rules or institutions, and nothing here involves the natural world.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'In a story about a girl trying to win back a scholarship, she loses her notes, then her bicycle breaks, then her mentor quits. These events mainly serve to', options: ['resolve the conflict through a series of small victories', 'provide background about her life before the story begins', 'shift the story\'s focus from the girl to her mentor\'s life', 'raise the stakes and pressure before the decisive moment'], correctAnswer: 3, explanation: 'Mounting complications are rising action: each setback intensifies the central conflict and builds toward the climax. They are obstacles rather than victories, they occur in the story\'s present rather than supplying backstory, and the focus stays on the girl\'s struggle.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'A story opens with a man sprinting through a train station, already late and bleeding from one hand, and only later explains how he was hurt. This opening uses', options: ['in medias res', 'a frame narrative', 'foreshadowing', 'a flash-forward'], correctAnswer: 0, explanation: 'Beginning in medias res means starting in the middle of the action and filling in earlier events later. A frame narrative encloses one story within another, foreshadowing hints at later events, and a flash-forward jumps ahead in time rather than starting mid-action.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'Near the end of a story, a boy who has idolized his older cousin watches him lie easily to their grandmother and suddenly sees him as small. In the structure of a short story, this moment is best described as', options: ['a climax that resolves the story\'s external conflict', 'a flashback that explains the cousin\'s past behavior', 'an epiphany that reorders the boy\'s understanding', 'a red herring that misleads readers about the cousin'], correctAnswer: 2, explanation: 'An epiphany is a sudden moment of insight, common at the turning point of short fiction; here the boy\'s view of his cousin changes in an instant. There is no external conflict being resolved, the moment happens in the present rather than the past, and it reveals the cousin\'s character rather than misdirecting readers.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'In a story, a nurse must choose between reporting a doctor\'s error and protecting her own job. How does this conflict most help a reader identify the story\'s theme?', options: ['The conflict\'s hospital setting fixes the story\'s time period', 'The choice she makes reveals the values the story tests', 'The conflict mainly supplies the doctor\'s backstory and training', 'The conflict keeps the plot moving but is unrelated to theme'], correctAnswer: 1, explanation: 'Conflict reveals values and stakes; what the nurse does under pressure shows what the story suggests about honesty, loyalty, and self-interest. The setting does not date the story, the conflict centers on her choice rather than the doctor\'s past, and conflict is a primary pathway to theme rather than separate from it.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'A village custom forbids widows to remarry, and the protagonist defies it publicly. The central conflict is best classified as', options: ['character versus self', 'character versus nature', 'character versus fate', 'character versus society'], correctAnswer: 3, explanation: 'When a character opposes a community\'s laws, customs, or institutions, the conflict is character versus society. The struggle here is with an external social rule rather than her own divided mind, the natural world, or a predetermined destiny.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'After the climax of a story, the scenes in which characters absorb the consequences and tension eases are called the', options: ['falling action', 'rising action', 'exposition', 'inciting incident'], correctAnswer: 0, explanation: 'Falling action follows the climax and shows consequences as tension subsides toward resolution. Rising action builds tension before the climax, exposition introduces the situation at the start, and the inciting incident sets the conflict in motion.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'A story ends with a mother holding a phone, about to call the son she has not spoken to in years; the story stops before she dials. What is the most defensible interpretation of this ending?', options: ['It confirms that the son refuses to answer his mother\'s call', 'It shows she has decided against calling, ending the conflict', 'It leaves reconciliation open, stressing her readiness', 'It implies the two have already forgiven each other in secret'], correctAnswer: 2, explanation: 'An open ending withholds the outcome, so the meaning lies in the mother\'s willingness to reach out rather than in the result. The story never shows the call, so a refusal cannot be confirmed; she is about to dial, not giving up; and nothing suggests a prior reconciliation.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'In a story, two sisters quarrel over who will inherit their late mother\'s farm; each recalls working beside their mother in the fields, and at the end neither can bring herself to sign the papers to sell it. Which claim about the conflict is most defensible for an AP essay?', options: ['The sisters\' quarrel over inheriting the farm drives the plot from their mother\'s death to the end.', 'The older sister\'s selfishness causes the quarrel, so the story is mainly a study of her greed.', 'The story treats the farm as a burden, and the sisters fight mostly to be rid of its upkeep.', 'The quarrel shows how inheritance can turn the sisters\' shared love of the farm into a rivalry.'], correctAnswer: 3, explanation: 'A defensible claim interprets the conflict and fits all the evidence: both sisters cherish their memories of the farm, so their fight grows out of shared love turned competitive. Tracing the quarrel through the plot is summary dressed as a claim, nothing singles out one sister as the selfish one, and their refusal to sign the sale contradicts the idea that they want to be rid of the farm.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'A student argues that a story\'s irony critiques a town\'s obsession with appearances. Which detail would best support this claim?', options: ['The mayor repaints the clinic\'s front wall though its roof still leaks', 'The town hosts a parade each summer that most of its residents attend happily', 'The narrator mentions that the town was founded more than a century earlier', 'At the harvest festival, the mayor gives a long speech about the town\'s history'], correctAnswer: 0, explanation: 'Strong evidence must demonstrate the claim; painting the visible wall while ignoring a leaking roof shows surface valued over substance, an ironic gap. A popular parade, the founding date, and a history speech do not show any gap between appearance and reality.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  { question: 'Which term names the event that first sets a story\'s central conflict in motion?', options: ['turning point', 'rising action', 'inciting incident', 'exposition'], correctAnswer: 2, explanation: 'The inciting incident is the event that launches the main conflict. A turning point shifts the direction of a conflict already under way, rising action is the series of complications that follows, and exposition provides the background that precedes the conflict.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 1, part: 1 },
  { question: 'As hail shatters the windshield, a character says, “What a lovely day for a picnic.” This line is an example of', options: ['situational irony', 'verbal irony', 'dramatic irony', 'hyperbole'], correctAnswer: 1, explanation: 'Verbal irony occurs when a speaker says the opposite of what they mean, as with calling a hailstorm a lovely picnic day. Situational irony concerns events rather than statements, dramatic irony depends on the audience knowing more than a character, and hyperbole is exaggeration rather than reversal.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-2', formSet: 2, part: 1 },
  // englit-short-fiction-3
  { question: 'In a story, a broken clock appears in the opening scene, again when the father loses his job, and again at his funeral. The clock is best described as', options: ['a one-time symbol with a single meaning', 'an allusion to a familiar myth', 'a motif whose repetition builds meaning', 'a piece of setting with no deeper role'], correctAnswer: 2, explanation: 'A motif is a recurring element whose meaning accumulates each time it returns, and the clock appears at three charged moments. It is not a one-time symbol because it recurs, nothing ties it to a myth, and its placement at key events shows it does more than furnish the room.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'A paragraph describes a wedding in bright, rushing sentences until the word “But” introduces the bride\'s glance at an empty chair, after which the sentences grow short and halting. This change is best described as', options: ['a tonal shift from celebration to unease', 'a change in point of view from bride to guest', 'a flashback to the bride\'s childhood plans', 'a resolution of the families\' main conflict'], correctAnswer: 0, explanation: 'A shift is a change in tone, perspective, or emphasis, often marked by a word like “But” and by changes in syntax; here the joy gives way to unease. The narration stays with the same perspective, the moment remains in the present, and the empty chair raises tension rather than resolving it.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'Read the passage: “Thomas checked the lock three times, then a fourth, then sat facing the door with his coat still on.” Which inference is best supported?', options: ['Thomas is about to set off on a long journey', 'Thomas has forgotten whether he owns a key', 'Thomas is eager for a friend\'s evening visit', 'Thomas fears that someone may try to come inside'], correctAnswer: 3, explanation: 'Inference draws a conclusion from textual clues: repeatedly checking the lock and watching the door suggest fear of an intruder. Someone about to travel would not lock himself in and sit down, the passage shows him using the lock rather than doubting his key, and locking out the world contradicts eager welcome.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'A student notices that rain appears in a story\'s first scene as a nuisance and in its final scene as a relief. What is the most analytical next step?', options: ['List the other weather images in the story to demonstrate the author\'s skill', 'Explain what the changed meaning of the rain reveals about the character\'s growth', 'Argue that rain conventionally symbolizes cleansing and rebirth in literature', 'Summarize the events that occur between the first rain and the final rain'], correctAnswer: 1, explanation: 'Tracking a motif means attending to recurrence and variation and then inferring what the change means. Listing images is device hunting without interpretation, treating a symbol as having one universal meaning ignores context, and summary replaces analysis.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'Which statement is phrased as a literary theme rather than a topic or a plot summary?', options: ['Pride can keep people from accepting the help they most need', 'The story explores the general topic of pride in a farming town', 'Pride and loneliness on a struggling family farm', 'A proud farmer refuses help from all his neighbors'], correctAnswer: 0, explanation: 'A theme is an insight about human experience expressed as a complete idea, as in the claim about pride blocking needed help. Naming a topic or listing subjects does not state an insight, and describing what the farmer does is plot summary.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'Theme in a short story usually emerges most clearly through', options: ['a single sentence in which the narrator states the moral', 'the title, which tells readers the story\'s main message', 'the author\'s biography and the era in which they lived', 'the pattern of characters\' choices and their outcomes'], correctAnswer: 3, explanation: 'Theme emerges through sustained patterns of choice, conflict, and consequence rather than a stated slogan. Few literary stories announce a moral outright, a title may hint at meaning but rarely states it, and biography is context rather than textual evidence.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'Read the passage: “Every evening Rosa saved the bread crusts for the birds. The winter her husband left, she ate the crusts herself, standing at the window where the birds waited.” What does the final sentence most suggest?', options: ['She has grown bored with feeding the birds every evening', 'Her hardship has narrowed the generosity she once showed freely', 'She is saving money to buy better seed for the birds', 'Her husband had always been the one who fed the birds'], correctAnswer: 1, explanation: 'The contrast between saving crusts for the birds and eating them herself implies new need after her husband\'s departure, with the waiting birds marking what she can no longer give. Nothing suggests boredom or savings, and the first sentence says Rosa, not her husband, fed the birds.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'Two stories both end with a character leaving home. One narrates the departure in long, lingering sentences; the other uses a single short line. What is the most precise way to explain how the endings convey different meanings?', options: ['The longer ending is more meaningful because it contains more detail', 'Both endings share one theme, since both characters depart from home', 'The syntax of each ending signals the character\'s feelings about the departure', 'The shorter ending shows that its author cared less about the departure'], correctAnswer: 2, explanation: 'Sentence structure shapes meaning: lingering syntax can suggest reluctance or attachment, while a clipped line can suggest finality or relief. Length does not equal significance, a shared event does not guarantee a shared theme, and brevity is a deliberate choice rather than a sign of indifference.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'How do motif and theme typically relate in a short story?', options: ['A motif states the theme directly the first time it appears', 'A motif and a theme are two different names for one idea', 'A motif matters mainly when it is unrelated to the theme', 'Recurring images gather meaning that points toward a theme'], correctAnswer: 3, explanation: 'Motifs build meaning through repetition, and that accumulated meaning supports a theme. A motif works by recurrence, not by stating the theme at once; the motif is the concrete pattern while the theme is the insight it suggests; and a motif detached from theme would carry little interpretive weight.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'A story titled “The Last Clean Shirt” repeats the phrase as a man dresses for a job interview after months of unemployment. The title most likely', options: ['describes the main place where the events unfold', 'names the story\'s antagonist and source of conflict', 'ties a small object to the man\'s dignity and anxiety', 'identifies the year in which the story\'s events occur'], correctAnswer: 2, explanation: 'Titles often point readers toward meaning; the last clean shirt makes the man\'s dwindling resources and his effort to keep his self-respect concrete. A shirt is not a place, an antagonist, or a date.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'In a story, a girl first sees her immigrant father\'s garden as embarrassing, later as ordinary, and finally as the only place she feels at home. This progression most clearly develops a theme about', options: ['how a sense of heritage can deepen over time', 'how gardening teaches patience to children of every age', 'how embarrassment fades once a person finally grows up', 'how fathers fail to understand their daughters\' needs'], correctAnswer: 0, explanation: 'The garden\'s changing meaning tracks the girl\'s growing connection to her father\'s culture, which points to a theme about heritage. Gardening skills are not the focus, maturity alone does not explain why the garden becomes home, and the father\'s understanding is never at issue.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'A story\'s opening describes a lake as “glassy and indifferent”; its closing, after a child is pulled from the water alive, describes the same lake with the same words. What is the most defensible reading of the repeated phrase?', options: ['The repetition shows that the narrator was unmoved by the rescue itself', 'The lake\'s unchanged surface highlights how much the human world has shifted', 'The phrase is repeated mainly to establish the setting more clearly for readers', 'Its waters have become a symbol of the child\'s recovery and of renewed hope'], correctAnswer: 1, explanation: 'Repeating the same description after a crisis sets nature\'s sameness against the characters\' upheaval. Describing the lake identically does not prove the narrator is unmoved, the setting was already established, and “indifferent” resists the hopeful meaning the symbol reading assigns.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'A story follows a soldier\'s first evening home from war: his mother cooks his favorite meal, but he eats standing at the window and leaves the house before dessert. Which thesis best states a complex theme for an AP essay?', options: ['The homecoming is a warm reunion that slowly begins to heal the soldier\'s wounds from the war.', 'The soldier stands at the window because he fears an enemy attack on his quiet hometown.', 'The soldier\'s homecoming offers comfort he cannot accept, because war has changed what comfort means to him.', 'The soldier\'s return home, from the meal to his early exit, fills one difficult evening.'], correctAnswer: 2, explanation: 'A complex thesis captures a tension within the work, here comfort that is offered but cannot be received. The details of eating apart and leaving early undercut a warm, healing reunion; reading the window as fear of attack takes one gesture too literally and has no support in the story; and tracing the evening\'s events is summary rather than a claim about theme.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'Which revision best adds complexity to the claim “The story shows that greed is wrong”?', options: ['Greed is wrong, and the author proves this point again and again in the story', 'Greed is shown to be wrong through the story\'s imagery and its use of diction', 'Greed is a theme the author develops throughout the entire length of the story', 'Greed tempts the story\'s decent characters too, blurring easy moral judgment'], correctAnswer: 3, explanation: 'Complexity comes from acknowledging tension or competing ideas, as when sympathetic characters are also tempted. Repeating the claim more forcefully, attaching device names, or noting that the theme runs throughout the story adds no nuance.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  { question: 'A recurring image, phrase, or idea that gains significance across a work is called a', options: ['motif', 'theme', 'symbol', 'epiphany'], correctAnswer: 0, explanation: 'A motif is defined by recurrence that accumulates meaning. A theme is the insight a work conveys rather than a recurring element, a symbol need not recur at all, and an epiphany is a sudden realization.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 1, part: 1 },
  { question: 'An AP multiple-choice question asks about the “function” of a paragraph within a passage. What should the student focus on?', options: ['How the paragraph would read restated in the student\'s own words', 'What the paragraph does in the text\'s overall development', 'Which literary device appears most often inside the paragraph', 'How the paragraph\'s content relates to the author\'s own life'], correctAnswer: 1, explanation: 'Function questions ask what a part does in the whole, such as introducing a contrast, shifting tone, or complicating a claim. Paraphrase identifies content rather than function, counting devices ignores purpose, and biography lies outside the passage.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-short-fiction-3', formSet: 2, part: 1 },
  // ── Domain: poetry ──────────────────────────────────────
  // englit-poetry-1
  { question: 'A poem titled “Letter from the Front” uses “I” to describe trench mud and cold rations, but the poet never served in a war. How should a reader refer to the voice of the poem?', options: ['As the poet herself, since the poem uses “I”', 'As the speaker, a persona distinct from the poet herself', 'As the poet\'s diary voice recording her own life', 'As an omniscient narrator reporting on the war'], correctAnswer: 1, explanation: 'AP readers refer to the voice of a poem as the speaker, a constructed persona that may differ from the poet. The first person does not make the poem autobiographical, the poet\'s own life does not include the war described, and an omniscient narrator would not speak as a soldier in the trench.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'Read the lines: “The mower came at noon and took / the clover, buttercup, and dock; / he whistled while the blades went round / and left the bees to curse the ground.” The speaker\'s attitude toward the mower is best described as', options: ['warmly admiring', 'bitterly enraged', 'wryly disapproving', 'calmly indifferent'], correctAnswer: 2, explanation: 'The whistling mower destroys the flowers casually, and the image of bees cursing the ground sides with the losers in a lightly comic way, so the attitude is wry disapproval. Nothing praises the mower, the playful rhyme and the cursing bees keep the tone short of rage, and taking the bees\' side shows the speaker is not indifferent.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'Which line relies most heavily on tactile imagery?', options: ['“The wool of his coat rasped against my cheek”', '“The chapel bells rang out across the hill”', '“A smell of burnt sugar drifted from the stall”', '“Gold light pooled along the empty hallway”'], correctAnswer: 0, explanation: 'Tactile imagery appeals to touch, and the rasping wool against a cheek is a sensation of texture. The bells appeal to hearing, the burnt sugar to smell, and the pooled light to sight.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'A poem\'s first stanza describes a childhood home with words like “bright,” “humming,” and “wide”; its final stanza describes the same rooms with “narrow,” “ticking,” and “dim.” Which claim best connects this pattern to meaning?', options: ['The house was physically remodeled between the first and last stanzas', 'The speaker prefers the house now that it feels quieter and more private', 'The final stanza describes a different house the speaker lives in now', 'The changed diction traces how time has shrunk the speaker\'s sense of home'], correctAnswer: 3, explanation: 'The same rooms are described with opposite connotations, so the change lies in the speaker\'s perception, shaped by time and loss. The poem gives no evidence of remodeling, words like “narrow” and “dim” do not suggest preference, and the stem specifies the same rooms.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'In literary analysis, diction refers to', options: ['a writer\'s word choice and its connotations', 'the arrangement of words into sentences', 'the pattern of stressed syllables in a line', 'the repetition of sounds at the ends of lines'], correctAnswer: 0, explanation: 'Diction is word choice, including the associations words carry. Arranging words into sentences is syntax, the pattern of stresses is meter, and repeated end sounds are rhyme.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'A speaker describes her grandmother\'s hands as “weathered” rather than “wrinkled.” What does this word choice most add?', options: ['A neutral, clinical description of the hands\' age', 'A suggestion that the grandmother was recently ill', 'An implication that the speaker finds the hands ugly', 'A sense of endurance through long exposure and work'], correctAnswer: 3, explanation: '“Weathered” connotes surviving long exposure, like wood or stone, so it suggests endurance and labor. It is less clinical than “wrinkled,” not more, it says nothing about illness, and its connotations are respectful rather than disgusted.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'Read the lines: “Iron sky. Iron fields. / The plow\'s iron mouth / chewing the iron ground.” What is the primary effect of repeating “iron”?', options: ['It establishes that the poem is set in a mining region', 'It shows the speaker\'s admiration for modern farm tools', 'It makes the whole landscape feel hard and unyielding', 'It creates a cheerful rhythm that eases the bleak scene'], correctAnswer: 2, explanation: 'Repeating one harsh word across sky, fields, plow, and ground fuses the landscape into a single cold, resistant image. Nothing indicates mining, the plow\'s “mouth” chewing the ground is not admiring, and the heavy repetition darkens rather than cheers the scene.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'In a poem set in a hospital waiting room, the speaker notices “the coffee\'s skin,” “the clock\'s thin hands,” and “the plastic fern\'s dust.” What do these images most suggest together?', options: ['The hospital is badly run, and the room should be cleaned more often', 'Anxiety has stalled time and narrowed the speaker\'s focus to lifeless details', 'The speaker is bored and largely indifferent to the patient\'s condition', 'The room\'s cheerful touches soften the worry the speaker feels inside'], correctAnswer: 1, explanation: 'Cooling coffee, a slow clock, and a dusty fake plant form an image cluster of stagnation and artificial life that mirrors anxious waiting. Reading the details as a complaint about cleaning is too literal, fixating on them signals anxiety rather than indifference, and the images are bleak rather than cheerful.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'How do imagery and tone typically interact in a poem?', options: ['Imagery sets the scene, but tone is set mainly by the poem\'s title', 'They are unrelated, as one is sensory and the other emotional', 'The sensory details chosen help create the speaker\'s attitude', 'Tone determines the rhyme scheme in which the images appear'], correctAnswer: 2, explanation: 'The connotations of the images a speaker selects are a main source of tone. A title may contribute but does not set tone alone, the two are closely linked rather than separate, and rhyme scheme is a formal choice rather than a product of tone.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'A speaker calls the city at dawn “a sleeping animal, breathing smoke.” This description combines imagery with', options: ['rhyme', 'alliteration', 'apostrophe', 'metaphor'], correctAnswer: 3, explanation: 'Calling the city an animal is an implied comparison, or metaphor, made vivid through sensory detail. The description does not rhyme, it has no repeated initial consonant sound, and the speaker does not address the city directly.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'A poem\'s first half lists a garden\'s flowers in lush, lingering detail; after the line “That was before the frost,” the images turn to black stems and brittle leaves. What does this shift most emphasize?', options: ['The speaker\'s skill as a gardener', 'How quickly beauty can be destroyed', 'The garden\'s location in a cold region', 'The speaker\'s preference for winter'], correctAnswer: 1, explanation: 'The abrupt turn from lush images to ruined ones dramatizes sudden loss. The poem does not praise gardening skill, the frost matters for its effect rather than as geography, and black stems and brittle leaves do not express delight in winter.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'In a poem about a state funeral, the diction moves from formal, Latinate words such as “magnificent” and “illumination” in the opening stanzas to plain monosyllables in the last: “I held her hand. She slept.” The shift most likely', options: ['turns from public ceremony to the speaker\'s private grief', 'shows the speaker forgetting the formal language of mourning', 'signals that the poem\'s audience has changed to young children', 'marks a move from grief toward relief that the ceremony is over'], correctAnswer: 0, explanation: 'Elevated diction suits public spectacle, while plain monosyllables bring the poem into an intimate memory of the dead woman. The change is a deliberate choice rather than a lapse, nothing suggests a new audience, and the quiet final image is tender rather than relieved.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'A poem describes the speaker\'s hometown through images of rust, peeling paint, and a diner sign missing two letters, then ends, “I would not fix a thing.” Which thesis about its imagery is strongest for the AP poetry essay?', options: ['Images of rust and peeling paint cast the town as a place the speaker loves for its wear.', 'Images of rust and peeling paint express the speaker\'s disgust at how far her town has fallen.', 'The diner sign missing two letters stands for the gaps in the speaker\'s memory of youth.', 'The poem moves through the town\'s rusted, peeling sights before ending with the old diner sign.'], correctAnswer: 0, explanation: 'A strong thesis links specific images to a defensible interpretation, and the closing line, “I would not fix a thing,” shows affection for the town\'s wear. Reading the images as disgust ignores that line, nothing in the poem connects the sign to failing memory, and walking through the images in order is summary rather than a claim.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'A student quotes the line “the field lay open like a letter no one sent.” Which commentary best explains the line?', options: ['This line includes a simile because it uses the word “like” in it', 'The field is very large and open, which is what the line describes', 'The simile fills the empty field with a sense of unspoken longing', 'This line shows that the poet was writing many letters at the time'], correctAnswer: 2, explanation: 'Strong commentary explains what the comparison means: an unsent letter suggests words never delivered, which charges the open field with longing. Naming the device is identification without interpretation, reading the field as merely large ignores the comparison, and biographical guesses are not textual analysis.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  { question: 'Language that appeals to the senses of sight, sound, touch, taste, or smell is called', options: ['diction', 'syntax', 'allusion', 'imagery'], correctAnswer: 3, explanation: 'Imagery is sensory language. Diction is word choice in general, syntax is sentence structure, and an allusion is a reference to another work, person, or event.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 1, part: 1 },
  { question: 'In the AP poetry analysis essay, which approach to a poem\'s imagery earns the most credit?', options: ['Identifying as many separate images as possible in the poem', 'Explaining how image patterns build a complex meaning', 'Paraphrasing each stanza in the order it appears', 'Describing a personal reaction to each of the images'], correctAnswer: 1, explanation: 'The rubric rewards evidence connected to a line of reasoning through commentary, so explaining how patterns of images create meaning earns credit. Cataloging images, paraphrasing, and personal response do not analyze how the poem works.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-1', formSet: 2, part: 1 },
  // englit-poetry-2
  { question: 'In poetry analysis, syntax refers to', options: ['a poet\'s choice of individual words and their connotations', 'the pattern of rhymes at the ends of a poem\'s lines', 'the emotional attitude a speaker takes toward a subject', 'the arrangement of words into phrases and sentences'], correctAnswer: 3, explanation: 'Syntax is sentence structure: word order, sentence length, and how clauses are arranged. Word choice is diction, end-rhyme patterns are rhyme scheme, and the speaker\'s attitude is tone.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'Read the line: “Not when the war ended, not when the letters stopped, not even when the house was sold — only then, at the gate, did she weep.” What is the main effect of the syntax?', options: ['The short clauses make her grief seem minor and quickly passing', 'Repeating “not” suggests that her tears at the gate were false', 'Delaying the main clause builds pressure toward the release of grief', 'The sentence moves the perspective from the woman to the gate'], correctAnswer: 2, explanation: 'The sentence holds back its main clause through a series of negations, so the weeping arrives as a long-delayed release. The clauses accumulate rather than minimize, nothing in the sentence casts doubt on her tears, which arrive as its climax, and the gate is the place of her grief rather than a new perspective.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'A poem refers to soldiers as “boys” rather than “men” throughout. What does this diction most emphasize?', options: ['Their lack of military skill', 'Their youth and vulnerability', 'The speaker\'s scorn for their conduct', 'How few of them were sent'], correctAnswer: 1, explanation: 'Calling soldiers “boys” stresses how young and exposed they are, which sharpens the poem\'s view of war\'s cost. The word concerns age rather than ability, it carries tenderness rather than scorn, and it says nothing about numbers.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'A poem calls the speaker\'s new city “a cage of lights” and, two lines later, “the first place I could breathe.” How should a strong reading treat these lines?', options: ['As a deliberate tension where freedom and confinement intertwine', 'As a contradiction showing that the poet revised the draft carelessly', 'As proof that the speaker\'s first impression of the city was simply wrong', 'As descriptions of two separate cities the speaker lived in over time'], correctAnswer: 0, explanation: 'Tension, competing ideas held together, generates complexity; the city can feel both enclosing and liberating. Treating it as a mistake or as a corrected impression discards half the evidence, and both lines describe the same new city.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'Tone in a poem is best defined as', options: ['the main subject or topic that the poem discusses', 'the emotional effect the poem produces in a reader', 'the speaker\'s attitude toward the subject or audience', 'the musical pattern of stressed and unstressed syllables'], correctAnswer: 2, explanation: 'Tone is the attitude conveyed through language choices. The subject is what the poem is about, the effect on a reader is mood, and the pattern of stresses is meter.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'How do readers usually identify a speaker\'s tone?', options: ['By finding the line in which the speaker names a feeling', 'By examining the connotations of the speaker\'s words', 'By learning the poet\'s mood when the poem was written', 'By counting the syllables and rhymes in each stanza'], correctAnswer: 1, explanation: 'Tone is inferred from language choices, especially the connotations of words, along with imagery and syntax. Speakers rarely announce their attitude outright, the poet\'s mood is outside the text, and counting syllables describes form without revealing attitude.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'Read the lines: “Congratulations on the promotion, Dad. / Another year of empty chairs at dinner, / another trophy for the cabinet.” The speaker\'s tone is best described as', options: ['sincerely proud', 'gently nostalgic', 'calmly indifferent', 'bitterly ironic'], correctAnswer: 3, explanation: 'The congratulation is undercut by “empty chairs” and by calling the promotion just another trophy, so the praise is bitterly ironic. The details reject sincere pride, the speaker is complaining about the present rather than fondly recalling the past, and the sting shows the speaker is not indifferent.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'A poem addressed to a sister who has moved away ends: “I water your plants. They are doing fine. / I am doing fine. The plants are doing fine.” Which reading of the speaker is best supported?', options: ['The repeated reassurance suggests the speaker is not fine', 'The speaker is content and wants the sister to stay away', 'The speaker is mainly concerned with keeping the plants alive', 'The speaker is answering the sister\'s request for plant news'], correctAnswer: 0, explanation: 'Repeating “fine” and folding the speaker\'s own state between two lines about plants signals loneliness the speaker will not state directly. Nothing suggests the speaker wants distance, the plants are a way of talking around the loss, and the poem includes no request from the sister.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'A speaker addresses a younger brother leaving for college in short commands: “Call. Eat something green. Don\'t be me.” How does the speaker\'s relationship to the listener shape the tone?', options: ['Formal authority keeps the speaker emotionally distant', 'Jealousy makes the commands sound mocking and cruel', 'Indifference shows in how brief the commands are', 'Protective affection mixes with a hint of regret'], correctAnswer: 3, explanation: 'An older sibling\'s practical advice conveys care, and “Don\'t be me” adds self-directed regret. The tone is intimate rather than formal, the commands are caring rather than mocking, and brevity here reads as urgency rather than indifference.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'A poem that speaks directly to the ocean as though it could listen uses', options: ['apostrophe', 'allusion', 'enjambment', 'hyperbole'], correctAnswer: 0, explanation: 'Apostrophe is a direct address to an absent person or to something nonhuman as if it could hear. An allusion is a reference to another work or event, enjambment is a sentence running past a line break, and hyperbole is exaggeration.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'A poem begins by mocking a neighbor\'s endless fussing over his roses and ends with the speaker kneeling in that garden after the neighbor\'s funeral. Which best describes the change in the speaker\'s stance?', options: ['Mockery hardens into open hostility', 'Respect fades into growing indifference', 'Mockery gives way to grieving respect', 'Curiosity turns into amused contempt'], correctAnswer: 2, explanation: 'Kneeling in the dead neighbor\'s garden signals that the speaker\'s early ridicule has become grief and respect. Nothing in the ending is hostile, the speaker begins with mockery rather than respect, and the opening attitude is mockery rather than curiosity.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'In a poem\'s final couplet, the speaker shifts from “I” to “we.” What is the most likely effect of this shift?', options: ['It reveals that a second speaker has been present from the start', 'It widens a private experience into a shared human one', 'It signals that the speaker wants to escape personal responsibility', 'It marks the poem\'s change from the present to the past tense'], correctAnswer: 1, explanation: 'Moving from singular to plural at the close commonly turns personal experience into a claim about people in general. A pronoun change alone does not reveal a hidden second speaker, nothing suggests evasion, and pronouns do not mark tense.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'In a poem about her diagnosis, the speaker describes appointments and medications in even, measured lines until the last stanza, where her syntax breaks into fragments. Which thesis best addresses how the speaker\'s tone conveys meaning?', options: ['The poem moves from the speaker\'s appointments to her medications to a final stanza of fragments.', 'The speaker\'s measured calm shows that she has made peace with her illness and faces it without fear.', 'The fragments in the last stanza show that her new medications have begun to cloud her thinking.', 'Her measured calm about the illness masks a fear that finally surfaces in the broken last stanza.'], correctAnswer: 3, explanation: 'The strongest thesis identifies the tone, shows its complexity, and ties it to the poem\'s structure: the calm is a surface that cracks in the fragmented ending. Listing the poem\'s stages is summary, reading the calm as untroubled acceptance ignores the broken last stanza, and blaming the medications reads a formal choice as a literal symptom without support from the poem.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'A student claims that the speaker\'s affection for her father is mixed with resentment. Which line best supports this claim?', options: ['“My father worked the night shift at the mill for thirty years.”', '“He taught me to drive on the gravel road behind the church.”', '“I wore his old coat all winter, hating how well it fit.”', '“The mill closed down the spring that I had turned seventeen.”'], correctAnswer: 2, explanation: 'Wearing the father\'s coat suggests closeness, while hating how well it fits shows resentment at resembling him, so the line holds both feelings. The other lines report facts or memories without the mixed attitude the claim requires.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  { question: 'The voice in a poem, which may differ from the poet, is called the', options: ['speaker', 'author', 'audience', 'protagonist'], correctAnswer: 0, explanation: 'The speaker is the voice of the poem, a persona that need not be the poet. The author is the real writer, the audience is who is addressed or reading, and protagonist names a central character in a narrative.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 1, part: 1 },
  { question: 'Which tone word most precisely describes a speaker who praises a rival\'s success while hinting at envy?', options: ['warmly celebratory', 'grudgingly admiring', 'openly hostile', 'detached and objective'], correctAnswer: 1, explanation: 'Precise tone words capture complexity; “grudgingly admiring” holds both the praise and the envy. “Warmly celebratory” misses the envy, “openly hostile” misses the praise, and “detached” misses the feeling behind both.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetry-2', formSet: 2, part: 1 },
  // englit-poetic-structure-form
  { question: 'The volta in a poem is best defined as', options: ['the final rhyming couplet of a sonnet', 'a turn in argument or feeling', 'a stanza of exactly four lines', 'a line that runs on into the next'], correctAnswer: 1, explanation: 'A volta is a turn, a shift in argument, tone, or feeling that often marks an interpretive pivot. A closing couplet may contain a turn but is not the definition, a four-line stanza is a quatrain, and a line running on is enjambment.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 1 },
  { question: 'A poet writes about a chaotic, bitter divorce in a strict villanelle whose two refrains return exactly on schedule. What is the most defensible effect of this formal choice?', options: ['The form shows that the divorce was calm and orderly from start to finish', 'The form is required for any poem about family or domestic subjects', 'The rigid form strains to contain emotions that keep breaking through', 'The form lets the poet avoid rhyme so the language sounds more natural'], correctAnswer: 2, explanation: 'Form creates expectations, and a tightly patterned form set against chaotic content produces tension, as the returning refrains suggest obsessive, unresolved feeling. Strict form does not make the subject orderly, no subject requires a villanelle, and the villanelle is a rhymed form.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 1 },
  { question: 'Read the lines: “He said he loved / nothing more than the sea.” How does the line break most affect meaning?', options: ['It first suggests a declaration of love that the next line redirects', 'It shows the speaker has finished the whole thought at the line\'s end', 'It slows the rhythm so the rhyme with the following line becomes clear', 'It separates two sentences that have no grammatical connection at all'], correctAnswer: 0, explanation: 'Lineation can create a momentary meaning: “He said he loved” briefly reads as complete, and the next line redirects the love toward the sea, hinting at what the speaker hoped to hear. The thought is not finished at the break, the lines do not rhyme, and they form one continuous sentence.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 1 },
  { question: 'In a Petrarchan sonnet, the octave catalogs a garden\'s spring beauty, and the sestet begins, “Yet none of this was planted by my hand.” What is the most likely function of the volta?', options: ['It introduces a closing couplet that sums up the octave\'s images', 'It continues the octave\'s catalog with further images of spring', 'It reveals that the garden described in the octave is imaginary', 'It turns from admiring the garden to the speaker\'s distance from it'], correctAnswer: 3, explanation: 'In a Petrarchan sonnet the volta usually falls at the sestet, and “Yet” signals a turn from admiration to the speaker\'s sense of separation from what she praises. The sestet is not a couplet, “Yet” breaks rather than continues the catalog, and nothing suggests the garden is unreal.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 1 },
  { question: 'A line of poetry that runs on into the next line without a grammatical pause is an example of', options: ['enjambment', 'caesura', 'an end-stopped line', 'a refrain'], correctAnswer: 0, explanation: 'Enjambment carries a sentence or phrase across a line break. A caesura is a pause within a line, an end-stopped line closes with a grammatical pause, and a refrain is a repeated line.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 1 },
  { question: 'How does a caesura typically affect a line of poetry?', options: ['It links the line smoothly to the one that follows it', 'It adds an extra rhyme in the middle of the line', 'It creates a pause that can stress a phrase', 'It marks the turn between the octave and the sestet'], correctAnswer: 2, explanation: 'A caesura is a pause within a line, often marked by punctuation, that can isolate words for emphasis. Linking a line to the next is enjambment, a mid-line rhyme is internal rhyme, and the octave-to-sestet turn is the volta.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 1 },
  { question: 'A poem’s first twelve lines praise a dead friend’s garden in three parallel four-line units, each ending “and still it grows.” The final two lines read: “But I, who planted nothing, cannot stay / To watch the thing he left me fade away.” What does the change in pattern at the close most suggest?', options: ['The garden will keep growing well without any human care at all', 'The friend never planted the garden that the speaker describes', 'The speaker turns from the garden’s endurance to his own failure to keep it', 'Mourning for the friend gives way to praise of the garden'], correctAnswer: 2, explanation: 'The three parallel units build a pattern of endurance (“and still it grows”), and the closing pair breaks that pattern to admit the speaker will not stay to tend what his friend left, so the turn sets the garden’s persistence against his own failure. The closing lines predict fading, not unaided growth; nothing questions who planted the garden; and the turn moves toward self-reproach, not praise.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 4 },
  { question: 'In a closed-form poem, the line “The door was always open” returns as a refrain at the end of each stanza. The early stanzas describe a welcoming childhood home; the last stanza describes the night the speaker’s father walked out. How does the refrain’s meaning most change by the end?', options: ['It shifts from a sign of welcome to a sign of exposure and loss', 'It stays a fond memory that softens the father’s departure', 'It becomes a literal detail cut off from the earlier stanzas', 'It reveals that the childhood home was never truly welcoming'], correctAnswer: 0, explanation: 'A refrain repeats the same words in new contexts, so its meaning accumulates: the open door that once meant welcome becomes the door the father leaves through, leaving the family exposed. The final context darkens the line rather than softening the loss, the repetition ties the last stanza to the earlier ones, and the early stanzas still present the home as welcoming.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 4 },
  { question: 'A poem about a mother\'s dementia breaks its later stanzas into increasingly short, scattered lines surrounded by white space. How does form connect to content here?', options: ['The fragmenting layout mirrors her unraveling memory', 'The short lines slow the poem to show her calm acceptance', 'The white space marks the poem\'s shift into a new setting', 'The scattered lines create a quick, playful rhythm'], correctAnswer: 0, explanation: 'Visual form can enact content; lines that break apart and drift into white space mirror the mother\'s memory coming apart. Nothing in the scattered layout suggests calm acceptance, the setting does not change, and the effect is disorienting rather than playful.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 1 },
  { question: 'A poem keeps a strict rhyme scheme throughout except in its final stanza, where the expected rhyme word is replaced by one that does not rhyme. What is the most likely interpretive effect?', options: ['The missing rhyme is an error the poet simply failed to correct', 'The broken pattern stresses a moment that resists neat resolution', 'The change signals that a new speaker has started to talk here', 'The break in pattern lessens the importance of the last stanza'], correctAnswer: 1, explanation: 'When a poem establishes a pattern, breaking it draws attention, and withholding the expected rhyme can enact a refusal of closure. Treating it as an error ignores the deliberate pattern, a missing rhyme does not by itself introduce a new speaker, and a break heightens rather than lessens emphasis.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 1 },
  { question: 'A poem\'s three stanzas move from morning to noon to night as the speaker recalls her marriage from its beginning to her husband\'s death. This structural choice', options: ['confines the poem\'s events to one literal day', 'shows that the speaker\'s memory is unreliable', 'splits the marriage into unrelated episodes', 'maps the course of a life onto a single day'], correctAnswer: 3, explanation: 'Organizing decades of marriage as one day makes the structure itself a metaphor for a life\'s arc and its ending. The events span years, so the day is figurative rather than literal; the orderly progression suggests clarity rather than unreliable memory; and the stanzas form a continuous arc rather than unrelated episodes.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 1 },
  { question: 'A poem ends each stanza with the refrain “the door was open”; in the final stanza the line becomes “the door was open, and I did not go.” How does the altered refrain function?', options: ['It confirms that the door had been closed for the entire poem', 'It shows that the refrain had no meaning before the last stanza', 'It turns a recurring image into a confession of a missed chance', 'It introduces a new setting that replaces the earlier house'], correctAnswer: 2, explanation: 'Refrains build expectation, and a varied final repetition can reveal what the repetition was circling: an opportunity the speaker never took. The door is open throughout, the earlier refrains gain meaning in retrospect rather than lacking it, and the setting stays the same.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 1 },
  { question: 'A poem moves from three long, flowing stanzas about the speaker\'s childhood church to two clipped couplets, written after her brother\'s death, in which she no longer addresses God. Which thesis best analyzes the poem\'s structure?', options: ['The poem\'s five stanzas fall into two groups, three long and flowing, then two clipped couplets.', 'The tight closing couplets show the speaker\'s faith growing firmer and more disciplined.', 'The long early stanzas show how vividly the speaker remembers her childhood church services.', 'The move from long stanzas to terse couplets enacts the speaker\'s loss of faith.'], correctAnswer: 3, explanation: 'A strong structural thesis links a formal change to meaning: the form contracts at the moment the speaker stops addressing God. Sorting the stanzas into groups describes form without interpreting it, reading the couplets as stronger faith ignores her silence toward God, and focusing on the early stanzas\' vividness addresses only half the poem and misses the shift.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 1 },
  { question: 'A student writes, “The poem is a sonnet with a volta in line 9.” Which addition would best turn this observation into commentary?', options: ['The turn exposes the speaker\'s praise as a mask for grief', 'The volta is a turn that occurs in many traditional sonnets', 'The sonnet has fourteen lines and is written in iambic meter', 'The poet chose the sonnet form because it is very famous'], correctAnswer: 0, explanation: 'Commentary explains what a formal feature does to meaning, as the claim about praise masking grief does. Defining a volta or listing more formal facts adds description, and guessing at the poet\'s motive replaces analysis with speculation.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 1 },
  { question: 'A poem with no regular rhyme or meter places the single word “Alone” on a line by itself after several long lines crowded with the names of friends. What is the most likely effect of this line break?', options: ['It shows that open forms have no structure worth analyzing', 'It marks a printing error that interrupts the poem’s flow', 'It signals that the poem will now begin to rhyme regularly', 'It isolates the word on the page, enacting the speaker’s solitude'], correctAnswer: 3, explanation: 'Open forms still make deliberate structural choices, and setting one word apart after crowded lines makes the page itself enact being alone. The break is a choice to analyze, not evidence that open forms lack structure or a printing error, and nothing suggests a turn to regular rhyme.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 1, part: 5 },
  { question: 'A poem rhymes exactly in every stanza (“night / light,” “day / away”) until the final stanza, about a broken engagement, pairs “trust” with “lost,” a near rhyme. What does the shift to a near rhyme most suggest?', options: ['The poet ran out of exact rhymes and accepted a weaker one', 'The near miss in sound mirrors a promise that no longer holds', 'The broken engagement is repaired by the poem’s final lines', 'The poem has moved into an open form with no rhyme at all'], correctAnswer: 1, explanation: 'When a poem sets up exact rhyme and then breaks it, the break carries meaning: sounds that almost but do not quite match echo a bond that has come apart. Treating it as a lapse ignores the established pattern, the stanza concerns a broken engagement rather than a repaired one, and a near rhyme is still rhyme, so the poem has not abandoned its pattern.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-poetic-structure-form', formSet: 2, part: 3 },
  // englit-sound-devices
  { question: 'The repetition of initial consonant sounds in nearby words, as in “cold, cruel current,” is called', options: ['assonance', 'consonance', 'alliteration', 'onomatopoeia'], correctAnswer: 2, explanation: 'Alliteration repeats the opening consonant sound of nearby words, here the hard c. Assonance repeats vowel sounds, consonance repeats consonants within or at the ends of words, and onomatopoeia imitates a sound.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'Which line relies most clearly on assonance?', options: ['“A low moan rolled across the stone”', '“Bright birds burst from broken branches”', '“The kettle\'s hiss, the faucet\'s drip”', '“Soft sighs slipped through the silent hall”'], correctAnswer: 0, explanation: 'Assonance repeats vowel sounds, and the long o in “low,” “moan,” “rolled,” and “stone” runs through the line. The bird line repeats the initial b and the sighs line the initial s, which is alliteration, and the kettle line relies on onomatopoeia.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'Read the lines: “Stop. Look. The road is ice. / The car slid on, and on, and on, and on.” How does the rhythm of the second line contribute to meaning?', options: ['Its short, clipped beats make the slide feel sudden', 'Its long, repetitive movement enacts the helpless slide', 'Its regular pattern shows the driver is fully in control', 'Its rhythm signals a cheerful shift in the speaker\'s mood'], correctAnswer: 1, explanation: 'After the clipped first line, the second line\'s repeated “and on” stretches out the motion so readers feel the car\'s uncontrollable sliding. The second line is long rather than clipped, the steady repetition suggests helplessness rather than control, and nothing in the moment is cheerful.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'In a poem about a factory, the line “clang and grind and clang and grind” is followed by “and then, at six, the hush.” What does the change in sound most emphasize?', options: ['The factory\'s machines have broken down for good at six', 'The speaker would rather have noise than evening quiet', 'The workers are forced to work longer hours than before', 'The sudden quiet feels almost unreal after relentless noise'], correctAnswer: 3, explanation: 'The pounding onomatopoeia and repetition build relentless noise, so the soft “hush” lands with startling contrast. The hush comes at a set hour, suggesting the shift\'s end rather than a breakdown; nothing expresses a preference for noise; and the lines say nothing about longer hours.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'How does sound typically contribute to meaning in a poem?', options: ['Sound devices matter mainly when a poem is read aloud', 'Sound devices are decorative and add little meaning', 'Sound devices replace the need for imagery and diction', 'Sound patterns can reinforce a poem\'s tone and ideas'], correctAnswer: 3, explanation: 'Sonic patterning intensifies tone and emphasis, so strong analysis links sound to interpretive effect. Readers hear sound patterns even in silent reading, treating them as decoration misses their effect, and sound works alongside imagery and diction rather than replacing them.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'A word that imitates the sound it names, such as “buzz” or “sizzle,” is an example of', options: ['alliteration', 'onomatopoeia', 'assonance', 'consonance'], correctAnswer: 1, explanation: 'Onomatopoeia names a sound by imitating it. Alliteration, assonance, and consonance are patterns of repeated sounds across words rather than single words that echo their meaning.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'Read the line: “The sibilant sea slid silver up the sand.” The repeated s sounds most likely', options: ['create a harsh, jarring sound suggesting violence', 'establish the rhyme scheme of the whole stanza', 'imitate the soft hiss of water moving over sand', 'signal a shift in the speaker\'s point of view'], correctAnswer: 2, explanation: 'The soft, hissing s sounds echo the sound of a wave sliding up a beach, matching sound to sense. S sounds are soft rather than harsh, repetition at the start of words does not set an end-rhyme scheme, and nothing in the line changes perspective.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'A poem describing a battlefield uses clusters of harsh consonants such as “crack,” “crunch,” “gut,” and “brick.” A later stanza about a wheat field shifts to “low,” “slow,” “gold,” and “roll.” What does this contrast in sound most convey?', options: ['A movement from violence toward stillness and calm', 'A shift from the speaker\'s present to a childhood memory', 'A change in rhyme scheme from couplets to quatrains', 'A contrast between two speakers\' opposing viewpoints'], correctAnswer: 0, explanation: 'Harsh stops evoke violence, while the long o sounds and liquid l\'s of the later stanza slow and soften the poem, enacting a move toward calm. Nothing indicates a memory, the words chosen show sound texture rather than rhyme scheme, and no second speaker appears.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'A poem about a hospital heart monitor keeps strict iambic meter until its last line breaks the pattern with three stressed syllables in a row: “Then. Stopped. Still.” What does the metrical break most suggest?', options: ['The speaker has fallen asleep beside the bed', 'The steady pulse has given way to death', 'The monitor is broken but the patient is well', 'The patient\'s heart is beating faster than before'], correctAnswer: 1, explanation: 'The regular iambic beat imitates a heartbeat, so its collapse into three heavy stresses, with words meaning stopping, enacts the heart\'s stopping. Nothing points to sleep or a malfunction, and the stressed, isolated words suggest stopping rather than speeding up.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'Which device describes the repeated st and nk sounds in “first and last” and “blank and think”?', options: ['consonance', 'assonance', 'alliteration', 'cacophony'], correctAnswer: 0, explanation: 'Consonance repeats consonant sounds in the middle or at the end of words, like the st and nk sounds here. Assonance repeats vowels, alliteration repeats initial consonants, and cacophony is harsh, discordant sound in general.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'A poem\'s opening stanzas use smooth, flowing sounds such as l, m, and long vowels, while its closing stanza is crowded with harsh k and t sounds. This change most likely signals', options: ['a switch from rhymed to unrhymed lines', 'a move from the present into the past', 'a darkening of tone as the poem ends', 'a change from one speaker to another'], correctAnswer: 2, explanation: 'A move from euphony to cacophony usually tracks a shift in tone toward tension or distress. Sound texture is separate from whether lines rhyme, and harsh consonants do not by themselves mark a change in time or speaker.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'A sonnet keeps regular iambic pentameter until line 11, where a heavy, irregular line appears: “Grief, grief, then the long dark road home.” What is the most defensible reading?', options: ['The poet made a metrical mistake that weakens the sonnet\'s effect', 'The irregular line marks the sonnet\'s switch into free verse form', 'The heavy stresses signal growing joy at the speaker\'s homecoming', 'The disrupted meter enacts how sorrow breaks the speaker\'s composure'], correctAnswer: 3, explanation: 'When an established meter breaks, the disruption usually carries meaning; crowded stresses on “grief” make the line heavy and halting. Treating it as an error ignores the pattern, one irregular line does not turn a sonnet into free verse, and “grief” and the “long dark road” rule out joy.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'Which sentence best analyzes sound for an AP poetry essay?', options: ['The poem uses alliteration, assonance, and consonance in several of its stanzas and its lines.', 'The final stanza has a lot of s sounds, which is an example of the device called sibilance.', 'The sounds in the poem show that the poet was a skilled musician as well as a fine writer.', 'The hissing s sounds in the final stanza make the snake\'s approach feel intimate and threatening.'], correctAnswer: 3, explanation: 'Analysis links a sound pattern to its effect on meaning, as the claim about the snake\'s approach does. Listing devices or naming sibilance only identifies features, and speculating about the poet\'s musical skill is biography rather than analysis.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'A student notices the alliteration in “blank, black, broken windows.” Which commentary best develops this observation?', options: ['Alliteration is the repetition of initial consonant sounds', 'The phrase describes the windows of a very old building', 'The hard b sounds hammer home the building\'s ruin', 'The poet probably liked the sound of words beginning with b'], correctAnswer: 2, explanation: 'Commentary explains the effect of a device in context: the repeated plosive b sounds give the description of ruin a blunt, battering force. Defining alliteration, paraphrasing the phrase, and guessing at the poet\'s preference do not explain meaning.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 1 },
  { question: 'The pattern of stressed and unstressed syllables in a line of poetry is called', options: ['rhyme', 'meter', 'diction', 'tone'], correctAnswer: 1, explanation: 'Meter is the measured pattern of stresses in a line. Rhyme is the repetition of end sounds, diction is word choice, and tone is attitude.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 1, part: 1 },
  { question: 'A poem describes a hummingbird in a line of quick, light syllables (“it flits and flicks and is gone in the glint of it”), then describes an old dog in heavy one-syllable words (“Old dog, stiff legs, slow step”). What does this contrast in sound most convey?', options: ['The speaker’s preference for the bird over the aging dog', 'A shift from the speaker’s memory to the speaker’s present', 'The bird’s speed against the dog’s labored, weighted movement', 'A sudden turn from describing animals to describing people'], correctAnswer: 2, explanation: 'Light, unstressed syllables speed a line up, while clustered stressed monosyllables and commas slow it down, so the sound enacts the bird’s darting and the dog’s stiff gait. The lines do not rank the animals, signal a change in time, or turn to human subjects; both describe the animals’ movement.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-sound-devices', formSet: 2, part: 4 },
  // ── Domain: longer-fiction ──────────────────────────────
  // englit-longer-fiction
  { question: 'In a novel, a protagonist\'s character arc refers to', options: ['the list of places the character travels to over the course of the plot', 'the physical description given when the character first appears', 'how the character\'s values shift across the narrative', 'the order in which the character meets the other people in the book'], correctAnswer: 2, explanation: 'A character arc traces development or stasis in values, choices, and self-understanding across the whole narrative. Travel routes, physical description, and the order of meetings are surface details that do not by themselves show development.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'A novel alternates chapters between a mother\'s account set in 1968 and her daughter\'s set in 2005, revealing a family secret from both sides. What does this structure most allow?', options: ['It lets the author avoid developing either character in depth', 'It establishes that only the mother\'s account can be trusted', 'It keeps the meanings of the two time periods fully separate', 'Each account recasts the other as the truth emerges'], correctAnswer: 3, explanation: 'Alternating perspectives make readers compare and revise each account, so structure drives interpretation and suspense. The alternation deepens both characters, nothing marks one narrator as solely reliable, and the point of interleaving the periods is that they illuminate each other.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'Why is it risky to state a novel\'s theme on the basis of a single chapter?', options: ['Theme emerges through patterns sustained across the entire work', 'Chapters in novels seldom contain thematic material of their own', 'A theme must be stated by the narrator in the final chapter', 'Each chapter of a novel develops its own unrelated theme'], correctAnswer: 0, explanation: 'In longer fiction, theme is built through sustained patterns of character, conflict, and image, so one chapter may give a partial or misleading picture. Individual chapters do carry thematic material, narrators seldom state themes outright, and a novel\'s chapters work together rather than separately.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'At the end of a long novel, the protagonist returns to the same job, town, and habits he had in the first chapter, despite everything that has happened. What is the most defensible interpretation?', options: ['The novel has no character arc and therefore no meaningful theme', 'His lack of change may be the point, exposing what keeps him trapped', 'The author must have planned a sequel to show his real development', 'His return shows that the novel\'s events had no effect on anyone'], correctAnswer: 1, explanation: 'Stasis can encode meaning as powerfully as change; a return to the starting point after upheaval can reveal the forces or flaws that hold a character in place. A static character does not make a novel themeless, sequel speculation is outside the text, and the claim that events affected no one overreaches.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'Which strategy best helps a reader analyze a character\'s development across a novel?', options: ['Focus closely on the character\'s first appearance alone', 'Memorize the character\'s physical traits and background', 'Compare the character\'s choices at several key stages', 'Count how many chapters the character appears in overall'], correctAnswer: 2, explanation: 'Development shows in how choices differ from beginning to middle to end. A first appearance shows only a starting point, physical traits do not reveal growth, and frequency of appearance says nothing about change.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'In a novel, how does a recurring setting, such as a family kitchen revisited in many chapters, typically build meaning?', options: ['It stays the same so that readers can keep track of where they are', 'It matters mainly in the chapter where it first appears', 'It lessens the need for development of the characters', 'Its changing condition tracks the household\'s fortunes'], correctAnswer: 3, explanation: 'A setting revisited over time can register change, as a kitchen that grows bare or crowded reflects a family\'s fortunes. Its value lies in how it changes rather than in orienting readers, its meaning accumulates across appearances, and it works alongside character development rather than replacing it.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'In chapter 2, Elena writes her name in the dust on her grandfather\'s piano. In chapter 30, after his death, she cannot bring herself to wipe the dust away. What does this pairing most suggest?', options: ['Elena now clings to traces of a life she took lightly', 'Elena has grown careless about keeping the house clean', 'Elena wants to learn the piano her grandfather played', 'Elena resents her grandfather for leaving her the piano'], correctAnswer: 0, explanation: 'Paired moments across a novel show development: the dust she once played in becomes something she cannot bear to erase. Her refusal is emotional rather than careless, nothing mentions learning to play, and preserving the dust suggests attachment rather than resentment.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'A coming-of-age novel, or Bildungsroman, is distinguished from other novel types mainly because it', options: ['follows a roguish hero through loosely linked comic episodes', 'centers on a young protagonist\'s moral and emotional growth', 'tells its story entirely through a series of personal letters', 'depicts an imagined society ruled by an oppressive regime'], correctAnswer: 1, explanation: 'A Bildungsroman traces a young person\'s formation into maturity. A roguish hero in loosely linked episodes describes the picaresque novel, a story told in letters is epistolary, and an oppressive imagined society is the mark of dystopian fiction.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'A novel opens with the protagonist\'s funeral and then narrates her life from childhood. How does this structure shape the reader\'s experience of her arc?', options: ['Readers feel suspense about whether she will survive the plot', 'Readers learn nothing about her until the closing chapters', 'Readers watch her choices knowing their end, adding irony', 'Readers are told the novel\'s theme directly in the opening'], correctAnswer: 2, explanation: 'Revealing the ending first shifts attention from what happens to how and why, and gives her hopeful choices an ironic shadow. Her death is already known, so survival is not in suspense; the narrative follows her from childhood onward; and a funeral scene does not announce a theme.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'A novel whose story is told through a character\'s letters is called', options: ['a picaresque novel', 'an epistolary novel', 'a historical novel', 'a frame narrative'], correctAnswer: 1, explanation: 'An epistolary novel is composed of letters or other documents. A picaresque novel follows a roguish hero\'s episodic adventures, a historical novel is set in a past era, and a frame narrative encloses one story inside another.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'In a long novel, a minor character who first seems purely comic is later revealed to have quietly sacrificed for the protagonist. How does this development affect interpretation?', options: ['It shows the author lost track of the character\'s original role', 'It confirms that comic characters in novels are rarely important', 'It turns the protagonist into a secondary figure in the novel', 'It complicates early judgments and asks readers to revise them'], correctAnswer: 3, explanation: 'Late revelations in longer fiction often reframe earlier scenes, pushing readers to reconsider how they judged a character. The shift is a designed reversal rather than a lapse, it shows a comic figure mattering a great deal, and the protagonist remains central.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'A novel\'s protagonist begins idealistic, becomes cynical in the middle chapters, and ends with a guarded hope. Which thesis best captures this arc for an AP essay?', options: ['Her hope survives disillusionment by growing wary, suggesting idealism must be tested to endure.', 'Her cynicism in the middle chapters is the novel\'s true verdict on the idealism of the young.', 'She moves from idealism through cynicism to a guarded hope across the novel\'s three parts.', 'At the end she returns to exactly the idealism she held at the start of the novel.'], correctAnswer: 0, explanation: 'A strong thesis interprets the arc\'s meaning rather than tracing its stages, here by explaining what a guarded hope suggests about idealism. Treating the middle-chapter cynicism as the verdict ignores the ending, listing the three stages is summary, and claiming a return to the original idealism overlooks that the final hope is guarded rather than naive.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'On the AP literary argument essay, students choose a work and respond to a prompt. Which approach best uses a novel as evidence?', options: ['Summarize the full plot so readers know the entire story', 'Select specific scenes that support a clear claim', 'Discuss as many characters as possible to show familiarity', 'Explain the novel\'s publication history and author\'s life'], correctAnswer: 1, explanation: 'The literary argument essay rewards a defensible claim supported by specific, well-chosen evidence and commentary. Plot summary, broad coverage of characters, and biographical background do not build a line of reasoning.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'Which evidence best supports the claim that a novel\'s wealthy family is morally decaying?', options: ['The family owns three homes and travels abroad every winter', 'The mother hosts large dinner parties every Saturday night', 'The father fires a loyal maid to cover up his own young son\'s theft', 'The son attends a prestigious boarding school in another city'], correctAnswer: 2, explanation: 'A claim about moral decay needs evidence of moral failure; scapegoating a loyal servant to protect a guilty son shows corruption directly. Owning homes, hosting parties, and attending a good school show wealth but not wrongdoing.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  { question: 'A story within a story, in which an outer tale introduces an inner one, is called', options: ['a frame narrative', 'a subplot', 'a flashback', 'an epilogue'], correctAnswer: 0, explanation: 'A frame narrative encloses an inner story within an outer one. A subplot is a secondary storyline, a flashback moves back in time within a narrative, and an epilogue is a concluding section after the main action.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 1, part: 1 },
  { question: 'A character type that recurs across many cultures and eras, such as the mentor or the trickster, is called', options: ['a foil character', 'an antihero', 'a dynamic character', 'an archetype'], correctAnswer: 3, explanation: 'An archetype is a recurring universal pattern of character, image, or plot found across cultures. A foil highlights another character by contrast, an antihero is a protagonist lacking conventional heroic qualities, and a dynamic character is one who changes over a story; none names a pattern shared across cultures.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction', formSet: 2, part: 1 },
  // englit-longer-fiction-2
  { question: 'A subplot in a novel is best described as', options: ['a summary of the main plot given in the final chapter', 'the background history of the novel\'s main characters', 'a secondary storyline that interacts with the main plot', 'the central conflict that drives the whole novel forward'], correctAnswer: 2, explanation: 'A subplot is a secondary line of action that can mirror or complicate the main plot. A summary is not a storyline, background history is backstory, and the central conflict belongs to the main plot.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'In a novel about a man who betrays his business partner, a subplot follows his teenage son, who lies to protect a friend and is punished for it. How does the subplot most likely function?', options: ['It contrasts the son\'s generous lie with his father\'s selfish deceit', 'It lightens the father\'s darker story by offering comic relief', 'It shows the son is already just as dishonest and selfish as his father', 'It has little thematic link and exists mainly to extend the novel'], correctAnswer: 0, explanation: 'Subplots often deepen or challenge the main plot; the son lies to shield someone else and pays for it, while the father deceives for his own gain, so the contrast complicates the novel\'s view of honesty. The son\'s punishment is not comic, his protective motive is the opposite of selfishness, and the parallel is clearly thematic.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'Early in a novel, a character jokes that the old bridge “won\'t hold another winter.” Two hundred pages later, the bridge collapses in a storm. The early line is an example of', options: ['a flashback', 'foreshadowing', 'an allusion', 'a red herring'], correctAnswer: 1, explanation: 'Foreshadowing plants an early hint of a later event. A flashback returns to an earlier time, an allusion refers to another work or event, and a red herring is a misleading clue, whereas this hint proves accurate.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'A novel reveals in its first chapter that a character will die but withholds how and why until the last chapter. How does this choice affect narrative tension?', options: ['Tension mostly drains away because the outcome is already known', 'Tension depends on readers forgetting the early revelation', 'Tension moves to whether the narrator is telling the truth', 'Suspense shifts from what will happen to how and why it happens'], correctAnswer: 3, explanation: 'Revealing an outcome early redirects suspense toward cause and process, sustaining tension with different questions. Knowing the outcome does not erase uncertainty about how it happens, the design depends on readers remembering the revelation, and nothing here raises the narrator\'s reliability.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'In a novel, a recurring image or idea that gathers significance across many chapters is a', options: ['subplot', 'flashback', 'motif', 'epilogue'], correctAnswer: 2, explanation: 'A motif recurs and accumulates meaning. A subplot is a secondary storyline, a flashback is a scene from an earlier time, and an epilogue is a closing section after the main action.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'How does a motif typically help develop a novel\'s theme?', options: ['It states the theme once, in the novel\'s opening paragraph', 'It distracts readers from the theme with decorative imagery', 'It appears mainly in the climax to explain the novel\'s meaning', 'Each return adds to or alters meaning tied to the theme'], correctAnswer: 3, explanation: 'A motif builds force through recurrence and variation, so each appearance can deepen or shift its connection to the theme. A motif works through repetition rather than a single statement, it supports rather than distracts from theme, and it recurs throughout rather than only at the climax.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'In a novel, mirrors appear when the heroine first dresses for society, when she lies to her husband, and when she smashes a mirror after his death. The motif most likely develops a theme about', options: ['the costs of owning expensive household items', 'the gap between a public self and a private one', 'the heroine\'s fear of growing older over time', 'the superstitions held by the heroine\'s class'], correctAnswer: 1, explanation: 'The mirrors appear at moments of performance and deception, and their breaking suggests a collapse of the public mask, pointing to a theme about public and private selves. The mirrors\' cost is never at issue, the moments concern deceit rather than aging, and nothing involves superstition.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'Two subplots in a novel both involve characters who refuse inheritances, one out of pride and one out of guilt. What is the most analytical way to treat them?', options: ['Compare the motives to show how the novel complicates its whole view of wealth', 'Treat them as repetitions that add little to the novel beyond its length', 'Focus only on whichever subplot contains the more dramatic single scene', 'Explain them as evidence drawn from the author\'s own family history'], correctAnswer: 0, explanation: 'Parallel subplots invite comparison; different motives for the same act reveal a more complex view of money and obligation. Dismissing them as repetition ignores the variation, choosing by drama skips the comparison, and biography lies outside the text.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'How do subplots and themes typically connect in longer fiction?', options: ['Subplots carry their own themes unrelated to the main story', 'Subplots exist mainly to give minor characters more scenes', 'Subplots can echo or complicate the theme from new angles', 'Subplots restate the main theme with little variation'], correctAnswer: 2, explanation: 'Secondary storylines often mirror or challenge the main plot\'s concerns, which deepens a novel\'s thematic complexity. Strong subplots are rarely unrelated, giving minor characters scenes is not their main purpose, and their value usually lies in variation rather than repetition.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'Which detail most clearly foreshadows a later betrayal?', options: ['A trusted friend hides a letter meant for the hero', 'The hero moves into a new apartment near the harbor', 'The hero\'s sister writes often from a distant city', 'The harbor freezes earlier than usual that winter'], correctAnswer: 0, explanation: 'A friend secretly taking the hero\'s letter hints at disloyalty to come. A move, letters from a sister, and an early freeze establish setting and relationships but do not point toward betrayal.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'A novel\'s motif of locked doors recurs throughout its first half; in the final chapter, the heroine leaves every door in the house open. What does this development most suggest?', options: ['She has stopped caring whether her house is safe', 'She is preparing to sell the house to new owners', 'She has lost the keys she carried in earlier chapters', 'She has moved from secrecy and fear toward openness'], correctAnswer: 3, explanation: 'When a motif reverses, the change usually marks character development; open doors after many locked ones suggest she no longer hides or guards herself. Reading it as carelessness, a sale, or lost keys takes the motif literally and ignores its accumulated meaning.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'A novel builds tension around whether two estranged brothers will reconcile, then ends with them silently mending a fence together. How should a reader interpret this resolution?', options: ['It shows they remain enemies who merely share a farm chore', 'It implies a partial peace enacted rather than spoken', 'It shows their conflict was minor from the very start', 'It leaves the novel without any resolution of its conflict'], correctAnswer: 1, explanation: 'Working together on a fence, an image of repair, implies reconciliation enacted through shared action even without words. Cooperation contradicts lasting enmity, the novel\'s sustained tension shows the conflict was serious, and the scene does resolve the conflict, though quietly.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'In a novel about a gentry family, a subplot follows the servants, who quietly slow their work after the master cuts their wages; the family never notices. Which thesis best uses this subplot in an AP literary argument essay?', options: ['The servants\' subplot runs alongside the gentry plot, following their work after the wage cut.', 'The servants\' slowdown supplies comic relief from the gentry family\'s more serious troubles.', 'The servants\' silent rebellion exposes the injustice that the gentry in the main plot ignore.', 'The subplot presents the master as a prudent manager whom hard times forced into the wage cut.'], correctAnswer: 2, explanation: 'A strong thesis argues how the subplot shapes meaning, here by revealing what the main plot\'s characters fail to see. Noting that the subplot runs alongside the main plot is description, nothing marks the slowdown as comic, and the subplot gives no evidence of hard times or prudence that would justify the wage cut.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'A student claims that a novel\'s repeated storms foreshadow the family\'s collapse. Which evidence best supports this claim?', options: ['Each storm arrives just before a new loss strikes the family', 'Storms are common in the coastal region where the novel is set', 'The family\'s house has a large porch that faces out to sea', 'The narrator mentions the weather in nearly every chapter'], correctAnswer: 0, explanation: 'Foreshadowing requires a link between the hint and what follows, and storms that consistently precede losses establish that link. Regional climate, the porch, and frequent weather references show storms exist but not that they anticipate collapse.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  { question: 'Which term names the sustained uncertainty and stakes that keep readers engaged across a long novel?', options: ['exposition', 'denouement', 'point of view', 'narrative tension'], correctAnswer: 3, explanation: 'Narrative tension is the sustained uncertainty and pressure that drives engagement. Exposition introduces the situation, the denouement follows the climax and ties up the action, and point of view is the perspective of the telling.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 1, part: 1 },
  { question: 'A clue that deliberately misleads readers about what will happen, as in a mystery, is called', options: ['foreshadowing', 'a red herring', 'a flashback', 'a motif'], correctAnswer: 1, explanation: 'A red herring is a false lead that diverts attention. Foreshadowing is a true hint of later events, a flashback returns to the past, and a motif is a recurring element that builds meaning.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-longer-fiction-2', formSet: 2, part: 1 },
  // englit-dramatic-structure
  { question: 'In a play, the exposition mainly', options: ['presents the moment of greatest tension in the action', 'establishes the situation and the conditions for conflict', 'resolves the central conflict and settles each fate', 'reverses the protagonist\'s fortunes in the final act'], correctAnswer: 1, explanation: 'Exposition introduces the context, relationships, and pressures that later scenes complicate. The moment of greatest tension is the climax, settling fates is the resolution, and a late reversal belongs to the turning point or catastrophe.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'A play opens with two servants gossiping about their master\'s sudden marriage and the return of his estranged son. What dramatic purpose does this conversation most serve?', options: ['It resolves the conflict between the master and his estranged son', 'It marks the turning point of the play\'s central line of action', 'It shows that the two servants are the play\'s true protagonists', 'It delivers background the audience needs through natural dialogue'], correctAnswer: 3, explanation: 'Opening conversations between minor characters are a classic way to deliver exposition without a narrator. The son\'s return sets up conflict rather than resolving it, the opening cannot be the turning point, and gossiping servants usually serve the exposition rather than lead the play.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'Halfway through a play, a mother discovers that the money she saved for years was stolen by her son, and everything afterward follows from this discovery. This moment is best described as the', options: ['exposition', 'denouement', 'turning point', 'falling action'], correctAnswer: 2, explanation: 'A turning point shifts the direction and stakes of the conflict, as this discovery does at the play\'s midpoint. Exposition comes at the start, the denouement comes at the end, and falling action follows the climax rather than redirecting the play.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'A tragedy ends with the stage nearly empty as a minor character orders the bodies removed and promises to restore the kingdom. What does this resolution most suggest?', options: ['Stability returns, but at a cost the scene makes plain', 'The minor character was secretly the play\'s villain all along', 'The tragedy\'s conflict is unresolved and will simply continue', 'The play\'s events were less serious than they first appeared'], correctAnswer: 0, explanation: 'Tragic resolutions often restore order through a surviving figure while the bodies and emptiness register the price. Nothing marks the survivor as a villain, the promise to restore the kingdom signals closure, and the deaths show the events were grave.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'A speech in which a character alone onstage reveals private thoughts to the audience is a', options: ['monologue', 'aside', 'soliloquy', 'dialogue'], correctAnswer: 2, explanation: 'A soliloquy is spoken by a character alone, voicing inner thoughts. A monologue is a long speech delivered to other characters, an aside is a brief remark to the audience while others are onstage, and dialogue is conversation between characters.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'A brief remark spoken to the audience that other characters onstage are understood not to hear is', options: ['an aside', 'a soliloquy', 'a monologue', 'a chorus'], correctAnswer: 0, explanation: 'An aside is a short remark the audience hears but other characters do not. A soliloquy is spoken when the character is alone, a monologue is addressed to other characters, and a chorus is a group that comments on the action.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'In one scene, Iris tells her fiancé, “I\'ve never been happier,” then turns to the audience and says, “Two more weeks of this.” What effect does this aside create?', options: ['It shows that Iris is now addressing a different character', 'It lets viewers share a truth her fiancé cannot hear', 'It resolves the play\'s central conflict between the lovers', 'It confirms that Iris believes what she told her fiancé'], correctAnswer: 1, explanation: 'An aside creates complicity between character and audience, here exposing the gap between Iris\'s words and her feelings. She speaks to the audience rather than another character, the remark deepens rather than resolves the conflict, and it contradicts what she told her fiancé.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'The audience watches a character slip poison into a cup; moments later, the hero raises that cup to toast his friend. Why is this staging especially effective in drama?', options: ['The audience is surprised, since the poison was never shown', 'The hero\'s toast reveals that he knew about the poison', 'The scene releases tension before the play\'s final act', 'Viewers\' knowledge turns an ordinary toast into dread'], correctAnswer: 3, explanation: 'This is dramatic irony: the audience knows what the hero does not, so a routine gesture becomes agonizing. The poisoning is shown rather than hidden, nothing indicates the hero knows, and the effect heightens rather than releases tension.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'A play\'s first act shows a father\'s tenderness with his young daughter before revealing, in Act 2, that he has embezzled from his employer. How does this ordering most affect the audience?', options: ['It makes the crime seem trivial, so no judgment is needed', 'It conceals his guilt until the play\'s very last scene', 'It builds sympathy that complicates our judgment of his crime', 'It reveals that the daughter is the play\'s antagonist'], correctAnswer: 2, explanation: 'Structure shapes audience alignment; establishing his tenderness first makes condemning him harder and the play more morally complex. Sympathy complicates judgment rather than removing it, the crime is revealed in Act 2 rather than at the end, and the daughter is not cast as an opponent.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'In classical tragedy, the protagonist\'s downfall often stems from a flaw or error in judgment known as', options: ['catharsis', 'peripeteia', 'anagnorisis', 'hamartia'], correctAnswer: 3, explanation: 'Hamartia is the tragic flaw or error that sets the downfall in motion. Catharsis is the audience\'s purging of pity and fear, peripeteia is the reversal of fortune, and anagnorisis is the moment of recognition.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'Across a three-act play, the stage directions call for the family\'s living room to be stripped of furniture bit by bit until it is bare in the final scene. What does this staging most convey?', options: ['A rise in the family\'s wealth and its sense of freedom', 'A steady loss of the family\'s stability and status', 'The family\'s happy return to simpler values', 'The long passage of years between the play\'s acts'], correctAnswer: 1, explanation: 'Staging that changes over time can externalize a family\'s decline, with each missing piece marking a loss. An emptying room suggests decline rather than wealth, a forced stripping of the home is not a cheerful choice of simplicity, and removing furniture piece by piece signals loss rather than merely marking elapsed time.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'A comedy ends with three weddings, but the stage directions note that one bride does not smile. What does this detail most add to the resolution?', options: ['A note of doubt that complicates the festive celebration', 'A sign that the comedy has secretly been a tragedy from the start', 'A signal that the bride will marry someone else after the play', 'A confirmation that the play\'s conflicts are now fully resolved'], correctAnswer: 0, explanation: 'Comedies traditionally end in marriage, so one unsmiling bride unsettles the celebration without overturning it. One detail does not convert the genre, the play gives no hint of a later marriage, and the detail suggests something remains unresolved.', difficulty: 'hard', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'A play places the heroine\'s confession at its midpoint rather than its end, and the second half follows the town\'s reaction. Which thesis best analyzes the play\'s dramatic structure?', options: ['Revealing the secret halfway through shifts the tension from discovery to consequence.', 'The play\'s first half builds to the heroine\'s confession, and its second half shows the town.', 'Placing the confession early is a flaw, since it drains the suspense from the second half.', 'The confession scene\'s halting dialogue reveals the heroine\'s shame about what she has done.'], correctAnswer: 0, explanation: 'A strong structural thesis explains how the placement of an event shapes tension: once the secret is out, the drama becomes about its consequences. Dividing the play into halves is summary, calling the placement a flaw misreads where the tension moves rather than analyzing it, and a claim about the scene\'s dialogue is too narrow to address structure.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'A student argues that a play\'s servants function like a chorus commenting on the action. Which evidence best supports this claim?', options: ['The servants enter carrying trays in nearly every single scene', 'Between scenes, the servants judge the family\'s choices', 'The servants wear matching uniforms that the family chose', 'The servants are played by the youngest actors in the cast'], correctAnswer: 1, explanation: 'A chorus comments on and interprets the main action, so servants who pass judgment between scenes fill that role. Carrying trays, wearing uniforms, and casting choices show their presence but not any commentary.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  { question: 'The purging of pity and fear that an audience experiences at the end of a tragedy is called', options: ['hubris', 'denouement', 'catharsis', 'hamartia'], correctAnswer: 2, explanation: 'Catharsis is Aristotle\'s term for the emotional release a tragedy produces in its audience. Hubris is excessive pride, the denouement is the unwinding after the climax, and hamartia is the hero\'s tragic flaw or error.', difficulty: 'easy', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 1, part: 1 },
  { question: 'Instructions in a script that describe setting, movement, or how lines are delivered are called', options: ['asides', 'soliloquies', 'dialogue tags', 'stage directions'], correctAnswer: 3, explanation: 'Stage directions guide setting, movement, and delivery and are a key source of evidence when analyzing drama. Asides and soliloquies are kinds of speech, and dialogue tags are the “he said” phrases of prose fiction rather than drama.', difficulty: 'medium', domain: 'longer-fiction', topicSlug: 'englit-dramatic-structure', formSet: 2, part: 1 },
  // ── Domain: character-narrative ─────────────────────────
  // englit-character-setting
  { question: 'Which detail is the strongest evidence of a character\'s values?', options: ['She has red hair and a faint scar above her left eye', 'She lives in a two-room flat above a shoemaker\'s shop', 'She was born in a small mining town in the far north', 'She spends her last coins on a stranger\'s child'], correctAnswer: 3, explanation: 'Choices, especially costly ones, reveal values; giving away her last money shows generosity and compassion. Appearance, address, and birthplace are descriptive facts that do not show what she cares about.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'In a story set in a drought-stricken farm town, a father sells his daughter\'s horse to pay the bank. How does the setting most shape this choice?', options: ['The town\'s beauty distracts him from his daughter\'s feelings', 'Economic pressure from the drought narrows his options', 'The drought is background with no bearing on his decision', 'The setting shows that he cares little for his daughter'], correctAnswer: 1, explanation: 'Setting includes economic and social conditions that constrain characters; the drought creates the debt that forces the sale. The town is not presented as beautiful, the drought directly causes the pressure, and a sale forced by debt does not show indifference to his daughter.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'A soldier is ordered to burn a village where his grandmother once lived. Whatever he decides, this conflict most clearly serves to', options: ['establish the time period of the war', 'introduce the antagonist\'s backstory', 'reveal the loyalties he values most', 'provide comic relief amid the violence'], correctAnswer: 2, explanation: 'Conflict clarifies values by forcing a choice between competing loyalties, here duty and family. The dilemma is not mainly about dating the war, it centers on the soldier rather than an antagonist\'s past, and nothing about it is comic.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'Read the passage: “Mrs. Albright straightened the portrait of her late husband every morning, though it never hung crooked, and told visitors that the house ‘ran itself, the way he liked.’” What does this characterization most suggest?', options: ['Her rituals keep her husband\'s authority alive in the house', 'She is a careless housekeeper who neglects the portrait', 'She is eager to remarry and leave the house behind her', 'Her husband\'s portrait is badly hung and keeps slipping'], correctAnswer: 0, explanation: 'Straightening a portrait that is never crooked and running the house “the way he liked” show that the dead husband still governs her habits. Daily straightening is the opposite of neglect, nothing hints at remarriage, and the passage states that the portrait never hangs crooked.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'In a play, characterization comes mainly from', options: ['what characters say and do onstage', 'a narrator\'s descriptions of their thoughts', 'chapter titles that summarize each scene', 'footnotes explaining each character\'s past'], correctAnswer: 0, explanation: 'Drama usually has no narrator, so characters are revealed through dialogue and action, supported by stage directions. A narrator\'s commentary belongs to prose fiction, and plays are not organized by chapter titles or footnotes.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'How does a playwright typically establish setting without a narrator?', options: ['Through a narrator who describes the setting before each act', 'Through program notes handed to audience members at the door', 'Through stage directions and the characters\' own words', 'Through the play\'s title, which always names its setting'], correctAnswer: 2, explanation: 'Playwrights build setting through stage directions, set design, and dialogue. Plays rarely use a narrator, program notes are not part of the script, and titles do not always name a setting.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'A play\'s opening stage direction reads: “A cramped apartment. Laundry hangs across the window. A single armchair, its stuffing showing, faces the television.” What does this setting most establish?', options: ['A wealthy family enjoying a quiet evening', 'A household strained for money and space', 'A historical palace from a distant era', 'A backdrop unconnected to the characters'], correctAnswer: 1, explanation: 'Cramped rooms, laundry blocking the window, and a worn chair signal financial strain and crowding that will press on the characters. None of the details suggest wealth or a palace, and setting details in stage directions are chosen to shape how we read the characters.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'In a play, a character who claims to be content in her small town keeps a packed suitcase visible under her bed in every scene. What does this staging most reveal?', options: ['A plan to visit relatives the following weekend', 'A lasting regret about a trip she took many years ago', 'A satisfaction with the town and its routines', 'A longing to leave that contradicts what she says'], correctAnswer: 3, explanation: 'In drama, objects onstage can contradict dialogue; a suitcase that stays packed scene after scene reveals a desire she does not voice. A weekend trip would not explain the permanence, a packed bag points toward a future departure rather than a past trip, and the suitcase undercuts rather than confirms her contentment.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'A play set entirely in one sweltering kitchen during a heat wave shows a family arguing over a will. How do setting and conflict interact?', options: ['The heat creates the family\'s conflict over the will', 'The kitchen distracts the family from their argument', 'The confining heat intensifies existing tensions', 'The setting shows that the conflict is about weather'], correctAnswer: 2, explanation: 'Setting can intensify an existing conflict; heat and confinement raise the pressure on a dispute that the will already caused. The heat does not create the dispute, the cramped kitchen concentrates rather than distracts, and the conflict concerns the inheritance.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'A minor character in a play whose caution highlights the protagonist\'s recklessness serves as a', options: ['hero', 'foil', 'chorus', 'antagonist'], correctAnswer: 1, explanation: 'A foil contrasts with another character to highlight his or her traits. A hero is the admired central figure, a chorus comments on the action, and an antagonist opposes the protagonist rather than simply contrasting with him.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'In Act 1, a character sits at the head of the dinner table giving orders; in Act 3, he sits at the edge while his daughter takes his chair. What does this staging change most convey?', options: ['A new set of rules for family seating', 'His growing affection for his daughter', 'A move of the dinner to a new house', 'A shift of power within the household'], correctAnswer: 3, explanation: 'Changes in blocking and position onstage can show changes in status; losing the head of the table signals lost authority. Reading it as a seating rule is too literal, the change concerns control rather than affection, and the scene takes place at the same table.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'A play\'s setting moves from a lively city café in Act 1 to the same café, shuttered and dusty, in Act 3, as the owner\'s friendships collapse. How should a reader interpret the change in setting?', options: ['The decaying café externalizes the owner\'s growing isolation', 'The café closed for reasons unrelated to the owner\'s life', 'The change shows the city is the play\'s real antagonist', 'The dust mainly shows that many years pass between acts'], correctAnswer: 0, explanation: 'When a setting decays as relationships collapse, the place mirrors the character\'s emotional state. The parallel timing ties the closure to the owner\'s life, the city is not cast as an opponent, and the passage of time matters less than what the decay reflects.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'In a story, Nora rents a room in a boarding house whose walls are so thin she can hear every neighbor; she hums while cooking and laughs loudly on the phone, then cries silently into her pillow at night. Which thesis best connects character and setting?', options: ['Nora\'s life in the boarding house with thin walls moves from cooking and calls to nights alone.', 'The thin walls force Nora to perform contentment, revealing how being overheard shapes a self.', 'Nora\'s humming and laughter show that the lively boarding house has made her genuinely happy.', 'Nora cannot afford a better room, and her poverty is the story\'s central concern.'], correctAnswer: 1, explanation: 'A strong thesis explains how setting shapes character and links that to meaning: because she can be heard, Nora performs a cheerfulness her silent crying contradicts. Following her day is summary, reading the humming as real happiness ignores the silent crying, and the story offers no evidence that money is its central concern.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'A student claims that a play\'s father is controlling. Which stage direction best supports this claim?', options: ['He enters wearing a gray coat and carrying a newspaper', 'He sits in an armchair near the window, reading quietly', 'He locks the telephone in a desk drawer and pockets the key', 'He laughs loudly at a joke his son tells during dinner'], correctAnswer: 2, explanation: 'Locking away the family\'s phone shows him restricting others\' contact, which directly supports the claim. His clothing, reading, and laughter reveal habits or mood but not control.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  { question: 'A character who remains essentially the same throughout a work is called', options: ['a static character', 'a dynamic character', 'a round character', 'a foil character'], correctAnswer: 0, explanation: 'A static character does not undergo significant change. A dynamic character changes, a round character is complex and may or may not change, and a foil highlights another character by contrast.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 1, part: 1 },
  { question: 'Which term names the emotional atmosphere a setting creates for the reader?', options: ['tone', 'theme', 'conflict', 'mood'], correctAnswer: 3, explanation: 'Mood is the feeling a work or setting evokes in the reader. Tone is the speaker\'s or narrator\'s attitude, theme is the work\'s insight about life, and conflict is the struggle between opposing forces.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-character-setting', formSet: 2, part: 1 },
  // englit-narration-pov
  { question: 'A story told by a narrator who uses “he” and “she” and reveals the thoughts of only one character uses', options: ['omniscient third-person point of view', 'first-person point of view', 'third-person limited point of view', 'second-person point of view'], correctAnswer: 2, explanation: 'Third-person limited narration stays outside the characters grammatically but enters one character\'s mind. Omniscient narration reveals many minds, first person uses “I,” and second person addresses “you.”', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'Read the passage: “I am the most patient man in this office,” Gerald wrote. “Today I explained the stapler to Linda only four times before I threw it.” How does this passage affect the reader\'s trust in Gerald?', options: ['It confirms that Gerald is patient with coworkers', 'His own account undercuts his claim of patience', 'It shows that Linda is the story\'s real narrator', 'It proves the office is unsafe for everyone there'], correctAnswer: 1, explanation: 'Gerald\'s own report of throwing the stapler contradicts his claim, signaling an unreliable narrator. The passage disproves rather than confirms his patience, Gerald rather than Linda is narrating, and one thrown stapler does not establish a general danger.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'A narrator describes her own childhood accident in a cool, detached voice, as though reporting on a stranger. What does this narrative distance most suggest?', options: ['She may still be holding that painful memory at arm\'s length', 'The accident was minor and left no lasting mark on her', 'The narrator is a different person from the child described', 'The narrator is omniscient and knows every character\'s mind'], correctAnswer: 0, explanation: 'Distance shapes tone and judgment; describing a personal trauma coolly can signal protective detachment from pain. A flat tone does not prove the event was trivial, she is narrating her own childhood, and detachment says nothing about access to other minds.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'A first-person narrator is a child describing her parents\' divorce; she reports her father\'s words exactly but misreads what they mean. What effect does this create?', options: ['Readers must accept the child\'s interpretation as the truth', 'Readers lose access to the dialogue between the parents', 'Readers see the father as the story\'s only reliable voice', 'Readers grasp adult pain the young girl cannot name'], correctAnswer: 3, explanation: 'A naive narrator creates a gap between what is reported and what is understood, so readers perceive more than the narrator does. Readers are invited to look past the child\'s interpretation, the dialogue is reported exactly, and the effect depends on the child\'s limited understanding rather than on the father\'s reliability.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'An omniscient narrator differs from a limited narrator mainly because the omniscient narrator can', options: ['speak only in the first person to readers', 'take part in the story\'s main events', 'report the thoughts of many characters', 'appear onstage as a character'], correctAnswer: 2, explanation: 'Omniscience means access to multiple characters\' minds and to information beyond any single viewpoint. Omniscient narrators usually narrate in the third person, they generally stand outside the action, and appearing onstage belongs to drama.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'How does point of view control what readers can know in a story?', options: ['It sets the story\'s time period and its location', 'It filters what events and thoughts get through', 'It fixes the number of characters in the plot', 'It determines the story\'s rhyme scheme and meter'], correctAnswer: 1, explanation: 'Point of view is the position from which a story is told, so it governs what information and judgments reach readers. Time and place belong to setting, the cast is a matter of plot and character, and rhyme and meter belong to verse.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'Read the passage: “You wake before the alarm. You already know what the letter will say, but you open it anyway.” This narration uses', options: ['second-person point of view', 'first-person point of view', 'third-person limited view', 'objective point of view'], correctAnswer: 0, explanation: 'Second-person narration addresses the protagonist as “you,” placing the reader in the character\'s position. First person uses “I,” third-person limited uses “he” or “she” with one character\'s thoughts, and objective narration reports only outward words and actions.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'A story told in the objective, or dramatic, point of view reports only what characters say and do. What interpretive demand does this place on readers?', options: ['Readers receive the narrator\'s judgment of each character', 'Readers share the protagonist\'s private thoughts directly', 'Readers learn the outcome before the events take place', 'Readers must infer feelings from action and dialogue'], correctAnswer: 3, explanation: 'Objective narration withholds inner thoughts and commentary, so readers must infer motives and emotions from behavior and speech. It offers no narrator judgments, no access to private thoughts, and no particular commitment to revealing outcomes early.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'A story about a bitter family feud is narrated by the youngest cousin, who loves people on both sides. How does this choice of narrator most shape the story?', options: ['It guarantees a neutral account of who started the feud', 'It lets the narrator report every adult\'s private thoughts', 'It turns the cousin into the main cause of the conflict', 'It invites sympathy for each faction in the feud'], correctAnswer: 3, explanation: 'A narrator attached to both sides filters events through divided loyalty, encouraging readers to understand each faction. Affection is not neutrality, a first-person cousin cannot report others\' private thoughts, and narrating the feud does not make him its cause.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'Which narrator is most likely to be unreliable?', options: ['A narrator who reports events in the order they occurred', 'A narrator who boasts of honesty yet hides his own petty theft', 'A narrator who describes the setting in sensory detail', 'A narrator who speaks in the past tense about her youth'], correctAnswer: 1, explanation: 'Unreliability arises when bias, self-interest, or deception distorts a narrator\'s account, as when a self-proclaimed honest man conceals theft. Chronological order, sensory description, and past tense are neutral narrative choices.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'A novel\'s narrator, now an old man, tells the story of his youth and occasionally interrupts with comments like “I did not understand then what she meant.” What does this dual perspective create?', options: ['A contrast between early experience and later insight', 'A second narrator who takes over the story\'s final half', 'A confusion about which events actually took place', 'A shift from first-person to omniscient narration'], correctAnswer: 0, explanation: 'A retrospective narrator holds two perspectives at once, the self who lived the events and the self who now understands them. It is the same narrator at two ages, the comments clarify rather than confuse, and he still speaks in the first person.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'Midway through a story, the narration shifts from a husband\'s perspective to his wife\'s, and readers learn she has known his secret all along. What is the main effect of this shift?', options: ['It confirms that the husband\'s narration was fully reliable', 'It drains the tension from the story\'s remaining scenes', 'It recasts earlier scenes as dramatic irony at his expense', 'It reveals that the wife is the story\'s true antagonist'], correctAnswer: 2, explanation: 'A shift in perspective can reframe what came before; knowing the wife\'s awareness, readers reread the husband\'s confident scenes with irony. His perspective is shown to be limited rather than fully reliable, new knowledge creates new tension, and knowing a secret does not make her an antagonist.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'A story about a family dinner is told in third-person limited point of view, focused on the anxious younger brother, who reads every pause and clink of silverware as a sign of a coming fight. Which claim best analyzes point of view in an AP essay?', options: ['The story\'s third-person limited narration stays with the younger brother for the whole dinner.', 'Seen through the anxious brother, the dinner is a reliable record of a family near a fight.', 'Third-person limited narration is the most effective way to build tension in short fiction.', 'Limiting the narration to the anxious brother turns an ordinary dinner into a scene of threat.'], correctAnswer: 3, explanation: 'Strong analysis explains how point of view shapes meaning, here by filtering a routine dinner through anxiety. Identifying the point of view is not analysis, treating an anxious character\'s perceptions as a reliable record ignores the filter, and a general ranking of narrative techniques says nothing about this story.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'A student argues that a narrator\'s account of a robbery is unreliable. Which detail best supports this claim?', options: ['She gives a vivid, carefully ordered account of the robbery', 'She reports the robbery to the police the following morning', 'She describes the thief\'s face, then says it was pitch dark out', 'She mentions that the robbery happened on a rainy Tuesday'], correctAnswer: 2, explanation: 'A narrator who contradicts herself gives readers direct reason to doubt her account. Vivid detail, a prompt report, and a stated date do not undermine her credibility.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  { question: 'A narrator who knows the thoughts and feelings of all characters is', options: ['limited', 'omniscient', 'objective', 'unreliable'], correctAnswer: 1, explanation: 'An omniscient narrator has access to every character\'s mind. A limited narrator knows one character\'s thoughts, an objective narrator reports only outward behavior, and unreliability concerns trustworthiness rather than range of knowledge.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 1, part: 1 },
  { question: 'A narrator whose account readers have reason to doubt, because of bias, ignorance, or deception, is called', options: ['unreliable', 'omniscient', 'objective', 'intrusive'], correctAnswer: 0, explanation: 'An unreliable narrator\'s credibility is compromised, so readers must read against the account. Omniscient refers to unlimited knowledge, objective to reporting only outward behavior, and intrusive to a narrator who comments openly on the story.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narration-pov', formSet: 2, part: 1 },
  // englit-narrative-complexity
  { question: 'In literary analysis, ambiguity means that', options: ['nothing in the text has a meaning readers can identify', 'the text supports more than one plausible reading', 'the author made an error that confuses readers', 'readers may choose whatever reading they prefer'], correctAnswer: 1, explanation: 'Ambiguity means multiple interpretations remain plausible because the text supports each with evidence. It does not mean the text is meaningless, it is usually deliberate rather than an error, and plausible readings still need textual support rather than personal preference.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'A story ends with a woman walking into the sea; the text never says whether she is swimming or drowning. Which approach best handles this ending in an essay?', options: ['Decide she is drowning and set aside the opposing details', 'Avoid the ending entirely, since it cannot be interpreted', 'Argue for a reading while granting the text\'s openness', 'Claim the ending is meaningless because it is unclear'], correctAnswer: 2, explanation: 'Sophisticated essays take a clear position while qualifying it to account for ambiguity. Ignoring contrary details weakens the argument, open endings can and should be interpreted, and uncertainty is a source of meaning rather than its absence.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'A narrator calls his late brother “the kindest man alive” but recounts several scenes in which the brother humiliates him. How should a reader treat this contradiction?', options: ['As a sign of the narrator\'s conflicted love', 'As an error that weakens the story\'s credibility', 'As proof that the brother was truly kind to him', 'As evidence the narrator barely knew his brother'], correctAnswer: 0, explanation: 'Contradiction can reveal the complexity of truth; the gap between praise and remembered cruelty suggests love tangled with hurt. It is a deliberate tension rather than a flaw, the scenes complicate rather than prove kindness, and the narrator\'s detailed memories show he knew his brother well.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'In a story, a girl buries her goldfish under the apple tree where, readers later learn, her mother scattered the grandmother\'s ashes. Which reading best captures the layered meaning of the burial?', options: ['The burial is a comic scene that lightens the story\'s mood', 'The tree mainly establishes the season in which events occur', 'The goldfish symbolizes the mother\'s wish to forget the past', 'A child\'s small ritual echoes the family\'s larger grief'], correctAnswer: 3, explanation: 'Layered meaning lets one moment work on several levels; the burial is literal for the child and resonant with the family\'s mourning. The shared site makes the scene poignant rather than comic, the tree\'s significance is emotional rather than seasonal, and a burial at the same place suggests remembrance rather than forgetting.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'Which phrasing best qualifies a claim about an ambiguous ending?', options: ['The ending hints at a reconciliation it never confirms', 'The ending proves that the two sisters reconcile completely', 'The ending is unclear, so nothing can be said about it', 'The ending shows that the sisters will stay estranged'], correctAnswer: 0, explanation: 'Qualifying language keeps a clear claim while acknowledging uncertainty. Claiming the ending proves or rules out reconciliation overstates the evidence, and declaring that nothing can be said abandons interpretation.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'How does contradiction usually create complexity in a narrative?', options: ['Competing details reveal careless editing by the author', 'Competing details resist a single, simple judgment', 'Competing details should be ignored in favor of one', 'Competing details make a text impossible to analyze'], correctAnswer: 1, explanation: 'When details pull in different directions, readers must hold tension rather than reduce a character or situation to one verdict. Such details are usually purposeful, ignoring them flattens the work, and contradiction gives analysis more to explain rather than less.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'Read the passage: “I forgave him years ago,” she said, and set his photograph face down on the table before pouring the tea. What does the passage most suggest?', options: ['She has fully forgiven him and is at peace with the past', 'She is preparing to show the photograph to her visitor', 'She dislikes the photograph because it was poorly taken', 'Her gesture belies her words, hinting the wound remains'], correctAnswer: 3, explanation: 'Turning his picture face down contradicts her claim of forgiveness, so the action reveals lingering hurt. The gesture undercuts peace, hiding the photo is the opposite of showing it, and the quality of the photograph is not at issue.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'A story\'s title, “The Rescue,” could refer to a dog pulled from a river or to the owner\'s own escape from a loveless marriage, which the story develops in parallel. What does the title\'s double reference most create?', options: ['Confusion that the author should have fixed with a new title', 'A focus on the dog that makes the marriage plot secondary', 'Layered meaning that links the literal event to an inner change', 'A plot summary that leaves little room for interpretation'], correctAnswer: 2, explanation: 'A title that applies to both an outer event and an inner change binds the two plots together and enriches each. The double reference is deliberate rather than confusing, it gives both rescues equal weight, and it invites rather than limits interpretation.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'How do ambiguity and theme connect in complex narratives?', options: ['Unresolved tensions can be central to its meaning', 'Ambiguity keeps a work from developing a theme', 'Theme can be stated once the ambiguity is cleared up', 'Ambiguity is a style choice with no link to the theme'], correctAnswer: 0, explanation: 'Complex works often make their thematic point through tensions they refuse to resolve. Ambiguity shapes theme rather than erasing it, readers need not resolve every uncertainty to state a theme, and openness is frequently part of what a work means.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'When one image works on both a literal and a symbolic level, such as a locked gate that also marks the barrier between social classes, the image carries', options: ['a plot hole', 'a flashback', 'layered meaning', 'a red herring'], correctAnswer: 2, explanation: 'Layered meaning means a single element operates on multiple interpretive levels at once. A plot hole is an inconsistency, a flashback is a jump to an earlier time, and a red herring is a misleading clue.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'Late in a story, the narrator admits to having lied about an earlier event. This late admission most likely', options: ['shows that the earlier scenes have no bearing on the story', 'forces readers to reread the earlier scenes with new suspicion', 'confirms that everything else the narrator said is true', 'ends the story\'s conflict by revealing who was at fault'], correctAnswer: 1, explanation: 'A late revelation of deception changes how readers understand everything before it. The earlier scenes gain new significance rather than losing it, one admitted lie makes the rest less certain rather than more, and the admission complicates rather than settles the conflict.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'A novel presents the same wedding night three times, from the bride\'s, the groom\'s, and a servant\'s view, with key details differing each time. What is the most defensible reading of this structure?', options: ['The servant\'s version must be correct, being the most neutral', 'The author forgot details and rewrote the scene inconsistently', 'Only the bride\'s version matters, since the wedding is hers', 'Truth emerges as partial, shaped by each observer\'s position'], correctAnswer: 3, explanation: 'Multiple conflicting accounts suggest that truth depends on perspective and that no single view is complete. Servants are not automatically neutral, the variation is a deliberate structure rather than carelessness, and dismissing two accounts discards the design.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'In a story, a son resents his father\'s silence, but after the funeral he finds that his father kept every one of his report cards in a desk drawer. Which thesis best demonstrates the complexity that the AP rubric\'s sophistication point rewards?', options: ['The son\'s resentment of his father\'s silence is justified, since the father withheld praise his whole life.', 'The son resents his father\'s silence, and the story\'s imagery and symbolism develop that resentment.', 'The drawer of report cards shows that the father secretly valued schooling above his own family.', 'Though the son resents his father\'s silence, the report cards suggest silence was the love the father could offer.'], correctAnswer: 3, explanation: 'The sophistication point rewards arguments that hold tension or complexity, as when resentment and hidden love are held together. Calling the resentment justified stays one-sided and ignores the report cards, pairing the resentment with a device list makes no fuller claim, and reading the drawer as valuing school over family misreads a gesture of love.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'Which revision best adds nuance to the claim “The narrator is lying”?', options: ['The narrator is lying, and this is clear from every scene in the story she tells', 'The narrator may believe her own version, making her deception a kind of self-deception', 'The narrator is lying, since narrators who speak in first person always lie', 'The narrator lies, and lying is a common device in a great many short stories'], correctAnswer: 1, explanation: 'Nuance acknowledges complexity, here that a narrator can deceive herself as well as readers. Asserting the lie more forcefully, generalizing about all first-person narrators, or noting that lying is common adds no insight.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  { question: 'A situation in which a text supports more than one reasonable interpretation is called', options: ['ambiguity', 'irony', 'paradox', 'allusion'], correctAnswer: 0, explanation: 'Ambiguity is openness to multiple plausible readings. Irony is a gap between expectation and reality, a paradox is a seemingly contradictory statement that reveals truth, and an allusion is a reference to another work or event.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 1, part: 1 },
  { question: 'A statement that seems self-contradictory but reveals a truth, such as “I must be cruel to be kind,” is', options: ['an oxymoron', 'an aside', 'a paradox', 'a hyperbole'], correctAnswer: 2, explanation: 'A paradox is a statement that appears contradictory yet expresses a truth. An oxymoron compresses contradiction into a short phrase such as “jumbo shrimp,” an aside is a remark spoken to a theater audience, and hyperbole exaggerates.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-complexity', formSet: 2, part: 1 },
  // englit-narrative-perspective
  { question: 'In literary analysis, focalization refers to', options: ['the author\'s purpose in writing the work', 'the central conflict around which the plot turns', 'the point in the story where tension peaks', 'whose perception filters the events'], correctAnswer: 3, explanation: 'Focalization identifies the consciousness through which events are perceived, which directs attention and sympathy. Authorial purpose, central conflict, and the climax are different concepts.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'A third-person story is told through the eyes of a jealous husband who notices every glance his wife gives other men. How does this focalization shape the story?', options: ['Readers receive an objective record of the wife\'s conduct', 'The wife\'s inner thoughts are fully revealed to readers', 'Ordinary moments take on a suspicious cast for readers', 'The husband appears calm and trusting toward his wife'], correctAnswer: 2, explanation: 'Focalizing through a jealous mind colors ordinary details with suspicion, so readers must separate perception from fact. The account is filtered rather than objective, the wife\'s thoughts stay hidden, and the husband\'s attention to every glance shows anything but trust.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'Read the passage: “The new neighbors,” Mrs. Pratt observed, “keep odd hours and have far too many visitors. Naturally I have said nothing to anyone.” She then telephoned three friends. What does the passage reveal about Mrs. Pratt\'s account?', options: ['Her observations are reliable because she watches so closely', 'Her judgments are biased, and her actions belie her claims', 'Her neighbors are clearly involved in some kind of crime', 'Her friends had asked her to report on the new neighbors'], correctAnswer: 1, explanation: 'Loaded judgments such as “far too many” reveal bias, and calling three friends right after claiming silence undercuts her credibility. Close watching does not guarantee fairness, odd hours and visitors do not prove a crime, and nothing suggests her friends asked for reports.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'A narrator insists his marriage is happy, yet mentions that his wife now sleeps in the guest room “for her back” and eats dinner at her sister\'s “most nights.” Which statement best describes the interpretive gap?', options: ['The details reveal an estrangement he will not admit', 'Readers learn that the wife has a serious back injury', 'Readers see that the sister disapproves of the narrator', 'Readers learn that the narrator is plotting to deceive her'], correctAnswer: 0, explanation: 'An interpretive gap is the distance between what a narrator presents and what readers can infer; the details point to estrangement that he explains away. Taking “for her back” at face value misses the pattern, the sister\'s opinion is never given, and his evasions look like self-deception rather than a plot against his wife.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'Which factor most often makes a first-person narrator unreliable?', options: ['Use of the past tense to describe earlier events in the story', 'Self-interest or limited knowledge that distorts the account', 'A large vocabulary and complex sentence structure throughout', 'The presence of dialogue between the narrator and others'], correctAnswer: 1, explanation: 'Narrators become unreliable when bias, self-interest, immaturity, or ignorance distorts what they report. Tense, vocabulary, and dialogue are ordinary narrative features that do not affect credibility.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'How do readers usually detect an unreliable narrator?', options: ['By checking whether the narrator speaks in the first person', 'By trusting the narrator less and less as the story goes on', 'By noticing gaps between the narrator\'s claims and facts', 'By looking for an author\'s note that warns readers directly'], correctAnswer: 2, explanation: 'Unreliability shows when a narrator\'s statements clash with details the text supplies. First person alone does not make a narrator unreliable, distrust must be grounded in evidence rather than applied automatically, and authors rarely announce unreliability.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'Read the passage: “Everyone at the party adored me. A few people left early, but that was surely the weather.” What does the second sentence most reveal?', options: ['The party was ruined by a sudden and dangerous storm', 'She was too busy to notice who left the party', 'The guests left early because they had other plans', 'The narrator explains away the threats to her self-image'], correctAnswer: 3, explanation: '“Surely the weather” is a rationalization; the narrator notices early departures but interprets them to protect her claim of being adored. No storm is described, she clearly noticed the departures, and the passage never gives the guests\' reasons.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'A story is focalized through a servant who notices only what the master\'s family wears and eats, never what they say. What does this restricted perspective most accomplish?', options: ['It reveals the servant\'s lowly position through what she can and cannot access', 'It gives readers an objective view of the family\'s private conversations', 'It shows that the family never speaks while the servant is in the room', 'It signals that the servant is the main antagonist of the family\'s story'], correctAnswer: 0, explanation: 'Analyzing what a perspective excludes is as revealing as what it includes; the servant\'s attention to clothing and food reflects her role and her exclusion from the family\'s world. The perspective omits the conversations, it does not prove the family is silent, and nothing casts her as an antagonist.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'A story about a factory fire is told from the owner\'s perspective, which dwells on lost machinery rather than injured workers. How does this perspective contribute to theme?', options: ['It shows that the story agrees machinery matters most', 'It provides a balanced account of the fire\'s full costs', 'Its blind spots expose the indifference it critiques', 'It has no connection to the story\'s larger meaning'], correctAnswer: 2, explanation: 'A narrow perspective can expose its own moral limits, inviting readers to judge what the owner ignores. The story need not share its narrator\'s values, the account is lopsided rather than balanced, and the choice of perspective is central to the story\'s meaning.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'A narrator who takes part in the story\'s events and tells them using “I” is a', options: ['third-person narrator', 'first-person narrator', 'omniscient narrator', 'objective narrator'], correctAnswer: 1, explanation: 'A first-person narrator is a character inside the story speaking as “I.” Third-person narrators stand outside the story, omniscient narrators know all characters\' minds, and objective narrators report only outward action.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'Over the course of a novel, the narrator\'s descriptions of his mentor move from worship to wariness as he uncovers the mentor\'s fraud. What does this changing perspective most show?', options: ['The mentor\'s sudden change in personality halfway through', 'His deliberate unreliability from the very first page', 'The author\'s own change of opinion while writing the novel', 'His growing insight, which readers come to share with him'], correctAnswer: 3, explanation: 'As a narrator learns, readers\' perspective develops with his, so the shifting descriptions trace his disillusionment. The mentor was a fraud all along rather than changing, early naivety is not the same as deliberate unreliability, and the author\'s opinions lie outside the text.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'A story is narrated by an adult recalling a childhood summer, but some passages slip into the child\'s present-tense perspective. What is the most likely effect?', options: ['Readers feel the past\'s immediacy within adult hindsight', 'Readers are told that the adult has forgotten that summer', 'Readers learn that two different narrators share the story', 'Readers see that the past events did not actually take place'], correctAnswer: 0, explanation: 'Shifting into a child\'s present tense makes the past vivid while the surrounding adult narration frames it with later understanding. The vivid passages show memory rather than forgetting, the child and adult are one person at two ages, and nothing suggests the events were invented.', difficulty: 'hard', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'A story about an eviction is narrated by the landlord, who records each step as a tidy ledger entry, such as “Unit 4B vacated, balance zero,” while the family\'s distress appears only in passing. Which thesis best analyzes perspective?', options: ['The landlord narrates the eviction step by step, recording each stage as a ledger entry.', 'Filtering the eviction through tidy ledger entries exposes how bookkeeping can mask cruelty.', 'The landlord\'s ledger entries show him to be a fair man who carefully follows the law.', 'The ledger entries show the landlord\'s skill with numbers, the source of his business success.'], correctAnswer: 1, explanation: 'A strong thesis explains how perspective produces meaning, here how the landlord\'s financial framing pushes the family\'s suffering to the margins. Describing the narration is summary, reading the ledger as proof of fairness accepts the narrator\'s framing uncritically, and his skill with numbers is beside the point of what the perspective hides.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'A student claims that a narrator\'s grief distorts her view of her sister. Which evidence best supports this claim?', options: ['She describes her sister\'s house as large and well furnished', 'She mentions that her sister lives in a different city now', 'She recalls that her sister is three years older than she is', 'She calls her sister heartless for laughing at the funeral'], correctAnswer: 3, explanation: 'Condemning her sister for one moment of laughter shows grief shaping a harsh judgment. The house, the city, and the age difference are neutral facts that reveal no distortion.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  { question: 'The perspective from which a story is told is its', options: ['conflict', 'exposition', 'point of view', 'structure'], correctAnswer: 2, explanation: 'Point of view names the narrative position that filters information and judgment. Conflict is the opposition of forces, exposition is introductory background, and structure is the arrangement of the work\'s parts.', difficulty: 'easy', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 1, part: 1 },
  { question: 'The difference between what a narrator presents and what readers can infer is actually true is called', options: ['an interpretive gap', 'a plot hole', 'a turning point', 'a narrative frame'], correctAnswer: 0, explanation: 'An interpretive gap is the distance between a narrator\'s account and the truth readers infer, and it drives deeper inference. A plot hole is an inconsistency, a turning point shifts a conflict\'s direction, and a narrative frame encloses one story in another.', difficulty: 'medium', domain: 'character-narrative', topicSlug: 'englit-narrative-perspective', formSet: 2, part: 1 },
  // ── Domain: figurative-language ─────────────────────────
  // englit-figurative-language
  { question: 'A metaphor differs from a simile in that a metaphor', options: ['compares two things that are exactly alike', 'compares without using “like” or “as”', 'gives human qualities to an object or idea', 'exaggerates a quality for dramatic effect'], correctAnswer: 1, explanation: 'A metaphor asserts an implied comparison directly, while a simile signals it with “like” or “as.” Comparisons join unlike things, giving human qualities to nonhuman things is personification, and deliberate exaggeration is hyperbole.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'A speaker calls her marriage “a long winter of good manners.” What does the metaphor most suggest?', options: ['A relationship that is polite but emotionally cold', 'A marriage that began during an especially cold season', 'A couple who enjoy formal events together each winter', 'A partnership that has grown warmer with the years'], correctAnswer: 0, explanation: 'Metaphor reveals how a speaker conceives of something; winter suggests coldness and endurance, and “good manners” suggests courtesy without intimacy. Reading the season literally misses the comparison, nothing suggests enjoyment, and winter implies chill rather than warmth.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'Which image most clearly creates a mood of dread?', options: ['“Sunlight spilled across the table and the bread”', '“Children\'s laughter drifted in from the yard”', '“The kettle sang softly on the warm stove”', '“A lone crow sat on the porch rail, watching the door”'], correctAnswer: 3, explanation: 'Imagery creates mood through its connotations; a crow, a traditional omen, fixedly watching a door suggests that something is coming. The sunlight, laughter, and singing kettle all evoke warmth and comfort.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'In a story, a widow winds her late husband\'s pocket watch every night, though she never checks the time. Late in the story, she lets it stop. What does the watch\'s stopping most likely signify?', options: ['Her anger at her husband over an old betrayal', 'Her need for a newer and more reliable watch', 'Her acceptance that her long vigil is over', 'Her forgetfulness as she grows older and tired'], correctAnswer: 2, explanation: 'A symbol gains meaning from context: winding the watch kept her husband\'s time going, so letting it stop marks the end of her vigil. Nothing suggests betrayal, the watch is not used to tell time, and the deliberate change late in the story signals meaning rather than forgetfulness.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'Giving human qualities to a nonhuman thing, as in “the wind whispered secrets,” is', options: ['apostrophe', 'metonymy', 'personification', 'allusion'], correctAnswer: 2, explanation: 'Personification attributes human actions or traits, like whispering, to nonhuman things. Apostrophe addresses an absent person or thing, metonymy substitutes a closely associated term, and an allusion refers to another work or event.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'How does figurative language typically shape meaning?', options: ['It reframes a subject through a revealing new comparison', 'It decorates a text without changing its meaning', 'It replaces literal meaning with a hidden code', 'It appears mainly to show off an author\'s vocabulary'], correctAnswer: 0, explanation: 'Figurative language transforms literal description into conceptual meaning by framing one thing in terms of another. It changes meaning rather than decorating, it adds a layer rather than encrypting the text, and its purpose is interpretive rather than showy.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'A poem compares two lovers to the legs of a drawing compass across several stanzas, one leg fixed at the center while the other roams. This sustained, elaborate comparison is called', options: ['a simile', 'a conceit', 'an allusion', 'a paradox'], correctAnswer: 1, explanation: 'A conceit is an extended, often surprising metaphor developed at length, as in John Donne\'s compass comparison in “A Valediction: Forbidding Mourning.” A simile is a single comparison using “like” or “as,” an allusion is a reference, and a paradox is a seeming contradiction.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'A novel\'s narrator describes a family debt as “a vine that grew up the walls of the house until the windows went dark.” What does this extended image most convey?', options: ['Debt as a minor problem that the family easily ignores', 'The family\'s love of gardening and of growing plants', 'A literal account of a house overgrown by thick ivy', 'Debt as a slow, living force smothering the home'], correctAnswer: 3, explanation: 'The vine metaphor makes debt organic and creeping, and darkened windows suggest the family slowly losing light and air. The image stresses menace rather than a minor problem, and reading it as gardening or literal ivy misses that it describes debt.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'How do imagery and symbolism typically work together in fiction?', options: ['Concrete details can accumulate symbolic weight', 'Symbols must be abstract and avoid concrete images', 'Imagery sets mood, but symbols mainly serve the plot', 'Symbols belong to poetry, and imagery belongs to prose'], correctAnswer: 0, explanation: 'Symbols are usually concrete things rendered through imagery that gather meaning across a text. Symbols are concrete rather than abstract, they serve meaning rather than only plot, and both devices appear in every genre.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'A reference to a well-known person, event, or text, such as calling a betrayer “a Judas,” is', options: ['an oxymoron', 'a hyperbole', 'an allusion', 'an apostrophe'], correctAnswer: 2, explanation: 'An allusion invokes a figure or story readers are expected to know, here the disciple who betrayed Jesus. An oxymoron joins contradictory terms, hyperbole exaggerates, and apostrophe addresses an absent person or thing.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'A story first describes a river as “a silver ribbon” and, after a drowning, as “a blade.” How does the change in figurative language function?', options: ['It shows that the river has changed its course over time', 'It tracks how loss changes the way the river is seen', 'It marks a shift in the season from summer into winter', 'It reveals that the narrator misremembers the river'], correctAnswer: 1, explanation: 'When figurative descriptions of the same thing change, they register a change in perception; a decorative ribbon becomes a cutting blade after a death. The river itself has not moved, the shift concerns grief rather than season, and nothing suggests faulty memory.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'A poem\'s speaker first calls her city “a hive,” praising its industry, and in the final stanza calls it “a hive with no queen.” What does the revision of the metaphor most suggest?', options: ['The city has just chosen a new and much more popular leader', 'The city\'s work has grown more orderly and efficient', 'The city\'s population has suddenly decreased', 'The city\'s busyness now seems directionless and empty'], correctAnswer: 3, explanation: 'Extending a metaphor can shift its meaning: a hive without a queen keeps working but has lost its center, suggesting purposeless activity. A missing queen implies no leader rather than a new one, losing the queen suggests disorder rather than greater order, and the hive is still busy rather than emptier.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'Which commentary best analyzes the metaphor “his promises were paper boats”?', options: ['This is a metaphor because it does not use “like” or “as”', 'Paper boats are small toys that children float in water', 'The image makes his word fragile, bound to sink once tested', 'The metaphor is creative and makes the writing more interesting'], correctAnswer: 2, explanation: 'Strong commentary explains what the comparison implies, here fragility and inevitable failure. Identifying the device by definition, explaining the literal object, or praising the writing does not interpret the metaphor.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'A student claims that a story\'s recurring caged bird symbolizes the wife\'s confinement. Which evidence best supports this claim?', options: ['The bird is a canary that sings loudly in the mornings', 'She opens the cage the night she leaves her husband', 'Her husband bought the bird at a market in the city', 'The cage hangs in the kitchen near the back window'], correctAnswer: 1, explanation: 'Freeing the bird at the moment she frees herself ties the symbol directly to her situation. The bird\'s song, its purchase, and the cage\'s location describe the object without connecting it to her confinement.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  { question: 'An object, person, or event that represents something beyond its literal meaning is', options: ['a simile', 'an image', 'a setting', 'a symbol'], correctAnswer: 3, explanation: 'A symbol is a concrete element that carries layered, abstract significance. A simile is an explicit comparison, an image is sensory description, and a setting is the time and place of a work.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 1, part: 1 },
  { question: 'A figure of speech in which a part stands for the whole, as in “all hands on deck,” is', options: ['synecdoche', 'apostrophe', 'personification', 'litotes'], correctAnswer: 0, explanation: 'Synecdoche uses a part to represent the whole, as hands stand for sailors. Apostrophe addresses an absent person or an abstraction, personification gives human traits to nonhuman things, and litotes is understatement through a negative, such as “not bad.”', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-figurative-language', formSet: 2, part: 1 },
  // englit-tone-speaker
  { question: 'A narrator describes a rival\'s lavish wedding with mock praise, calling the twelve-tier cake “a modest snack” and the fireworks “a quiet touch.” Which word best names the narrator\'s tone?', options: ['sardonic', 'nostalgic', 'reverent', 'melancholy'], correctAnswer: 0, explanation: 'The deliberate understatement is mock praise: calling extravagance modest and quiet signals a mocking, cynical stance, which is what “sardonic” names. Nothing in the lines looks back fondly on the past, the praise is ironic rather than respectful, and the tone is cutting rather than sad.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'Read the lines: “Of course the committee was thrilled with my proposal. They thanked me warmly and filed it under ‘Later.’” The speaker\'s tone is best described as', options: ['genuinely grateful', 'wryly resigned', 'openly furious', 'anxiously hopeful'], correctAnswer: 1, explanation: '“Of course” and the punch line about a file marked “Later” show the speaker sees through the committee\'s warmth with dry humor and little expectation. The irony rules out sincere gratitude, the restraint rules out open fury, and the speaker expects nothing, so hope is absent.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'A poem about a factory closing is spoken by the factory\'s longtime night guard. How does this speaker\'s position most affect the poem?', options: ['It gives an insider\'s intimate, unofficial view of the loss', 'It offers the owners\' financial explanation for the closing', 'It provides a detached, statistical account of the job losses', 'It ensures the poem celebrates the closing as a kind of progress'], correctAnswer: 0, explanation: 'A speaker\'s relationship to the subject shapes authority and bias; a longtime guard knows the building intimately but speaks from outside management. He would not supply the owners\' finances, his long tenure makes detachment unlikely, and nothing about his position implies celebration.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'A speaker spends three stanzas mocking her hometown\'s gossip and dull routines, then ends: “Still, I know which porch light means come in.” How does the final line shift the tone?', options: ['Mockery hardens into open contempt for the whole town', 'The speaker reveals a plan to move back home quite soon', 'The tone stays mocking, and the last line is sarcastic', 'Mockery softens into reluctant affection and belonging'], correctAnswer: 3, explanation: '“Still” signals a turn, and knowing the welcoming porch light shows that she belongs despite her complaints. The line is warmer rather than harsher, it says nothing about moving back, and its sincerity contrasts with the earlier mockery rather than continuing it.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'A speaker\'s tone is conveyed mainly through', options: ['the poem\'s length and its number of stanzas', 'the publication date printed beneath the poem', 'the reader\'s own mood while reading the poem', 'language choices such as diction and syntax'], correctAnswer: 3, explanation: 'Tone is the attitude conveyed through language choices, especially word connotation and sentence structure. Length and date do not convey attitude, and the reader\'s own feelings describe mood rather than the speaker\'s tone.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'Why is a label like “positive” or “negative” usually too vague for an AP tone answer?', options: ['AP readers reward long words over short ones', 'Tone labels are rarely used on the AP exam', 'Precise terms capture mixed attitudes', 'Texts on the exam are mostly neutral in tone'], correctAnswer: 2, explanation: 'Literary texts often hold complex or shifting attitudes, so precise tone vocabulary such as “nostalgic” or “bitterly ironic” shows real understanding. Length of word is not the point, tone is tested regularly, and exam texts are rarely neutral.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'Read the lines: “Mother, the garden you planted / has gone to seed. I let it. / Forgive me, or don\'t.” The speaker\'s tone is best described as', options: ['joyful and carefree', 'guilty yet defiant', 'coldly indifferent', 'purely apologetic'], correctAnswer: 1, explanation: '“Forgive me” expresses guilt, while “I let it” and “or don\'t” assert defiance, so the tone holds both. Nothing is joyful, addressing the mother and asking forgiveness rule out indifference, and the closing “or don\'t” undercuts a purely apologetic reading.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'A speaker addresses an employer formally as “Esteemed Sir” but describes the job as “twelve honored hours of breathing dust.” What does this mix of diction create?', options: ['Irony that sets courtesy against resentment', 'Sincere gratitude for steady and respectable work', 'Confusion about whom the speaker is addressing', 'A neutral record of the speaker\'s working hours'], correctAnswer: 0, explanation: 'Pairing elevated words like “esteemed” and “honored” with “breathing dust” turns the courtesy ironic and exposes resentment. The harsh image undercuts sincerity, the address is clear, and the loaded diction is anything but neutral.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'A speaker writes to the grandson she has never met, explaining why she left the family decades ago. How does this relationship to the listener most shape the voice?', options: ['It makes the voice formal, distant, and purely factual', 'It drains the emotion, since the two have not met', 'It mixes self-defense with a plea to be understood', 'It turns the letter into a set of instructions'], correctAnswer: 2, explanation: 'Addressing an unknown grandson about an old departure creates a voice that justifies and seeks connection at once. The stakes make a purely factual or emotionless voice unlikely, and explanation and appeal, not instructions, drive the situation.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'The distinctive personality and style that come through a speaker\'s or narrator\'s language are called', options: ['plot', 'setting', 'structure', 'voice'], correctAnswer: 3, explanation: 'Voice is the distinctive presence created by diction, syntax, and tone. Plot is the sequence of events, setting is time and place, and structure is the arrangement of parts.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'A poem moves from questions (“Where did you go?”) to flat statements (“You went.”). What does this syntactic shift most suggest about the speaker?', options: ['Anger gives way to forgiveness', 'Searching gives way to acceptance', 'Joy gives way to boredom', 'Confusion gives way to fear'], correctAnswer: 1, explanation: 'Shifts in syntax can mark shifts in stance; questioning signals searching, and the bare statement signals acceptance of the loss. The questions express searching rather than anger, nothing in the poem is joyful, and the final statement sounds settled rather than afraid.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'A speaker praises a soldier\'s “glorious” sacrifice in the first stanza, but the final stanza shows his mother folding his shirts “into a drawer no one opens.” How does this shift affect the earlier praise?', options: ['It makes public rhetoric sound hollow beside grief', 'It confirms that the sacrifice was glorious after all', 'It turns the focus to the mother\'s skill at housework', 'It shows that the soldier is alive and coming home'], correctAnswer: 0, explanation: 'A late shift can recast what came before; the quiet image of unworn shirts in an unopened drawer makes the earlier “glorious” sound empty. The ending undercuts rather than confirms the praise, the folding matters as an image of grief, and a drawer no one opens implies he will not return.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'A poem\'s speaker teases her aging father about his hearing aid and his slow driving, but in the last stanza she notices his hands shaking on the wheel and stops joking. Which thesis best analyzes tone for the AP poetry essay?', options: ['The speaker jokes about her father\'s hearing aid and driving, then notices his shaking hands.', 'The speaker\'s teasing reveals a mocking contempt for her father that lasts to the final line.', 'The speaker\'s jokes about the hearing aid show she is embarrassed to be seen with her father.', 'The speaker\'s affectionate teasing turns to tenderness as she recognizes her father\'s fear.'], correctAnswer: 3, explanation: 'A strong tone thesis names a precise tone, traces how it develops, and links the shift to meaning. Listing what happens is description, claiming lasting contempt ignores that she stops joking, and embarrassment is not supported by anything in the poem.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'A student claims that a speaker\'s cheerful tone masks anxiety. Which line best supports this claim?', options: ['“What fun!” I laughed, and checked the stove again', '“We drove to the lake and swam until the sun went down”', '“The picnic basket held sandwiches and cold lemonade”', '“My sister laughed and splashed me from the dock”'], correctAnswer: 0, explanation: 'The cheerful phrase paired with compulsively rechecking the stove shows anxiety beneath the surface tone. The other lines describe pleasant events without any sign of hidden worry.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  { question: 'The attitude a speaker or narrator conveys toward a subject or audience is', options: ['mood', 'theme', 'tone', 'diction'], correctAnswer: 2, explanation: 'Tone is the speaker\'s attitude. Mood is the feeling evoked in the reader, theme is the work\'s insight about life, and diction is word choice, which is one source of tone.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 1, part: 1 },
  { question: 'A change in a speaker\'s attitude, often marked by words like “but” or “yet,” is called', options: ['a motif', 'a shift', 'an allusion', 'a conceit'], correctAnswer: 1, explanation: 'A shift is a change in tone, stance, or emphasis, often signaled by a contrasting conjunction. A motif is a recurring element, an allusion is a reference, and a conceit is an extended metaphor.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-tone-speaker', formSet: 2, part: 1 },
  // englit-symbol-motif-fiction
  { question: 'Why is it a mistake to assume that a symbol has one fixed, universal meaning?', options: ['Symbols in fiction carry little meaning of their own', 'A symbol\'s meaning is set by the reader\'s feelings', 'Its meaning depends on context in the text', 'Symbols mean what authors say they mean in interviews'], correctAnswer: 2, explanation: 'Symbol meaning is built by the work itself and can evolve as the text develops. Symbols do carry meaning, interpretations must be grounded in the text rather than personal feeling, and authors\' comments lie outside the text.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'In a story, a family\'s dining table appears at a holiday feast, at a tense meal after a bankruptcy, and finally at auction. The table is best understood as', options: ['a detail that sets the story\'s historical era', 'a motif charting unity and then decline', 'a symbol with one fixed meaning throughout', 'a red herring that distracts from the plot'], correctAnswer: 1, explanation: 'A recurring object that appears at key moments works as a motif whose meaning develops; the table moves from togetherness to strain to loss. It does not date the story, its meaning changes rather than staying fixed, and it is central to the plot rather than a distraction.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'A green dress appears three times in a novel: bought for a dance, worn to a funeral, and given to a younger cousin. Which analytical move best tracks this pattern?', options: ['Explain how its meaning changes in each context', 'List the colors of the other garments in the novel', 'Argue that green conventionally symbolizes envy in literature', 'Summarize the three scenes in chronological order'], correctAnswer: 0, explanation: 'Pattern development means tracking recurrence and variation, then inferring what the changes show. Cataloging garments is device hunting, assigning a universal color meaning ignores context, and summary does not interpret.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'In a story, rain accompanies the early scenes of loneliness, but in the final scene a character stands in the rain laughing with a new friend. What does this variation most suggest?', options: ['The author lost track of what the rain meant before', 'The rain now symbolizes the friend\'s hidden sadness', 'Weather details are background with no real meaning', 'The same motif now marks her changed inner state'], correctAnswer: 3, explanation: 'When a motif recurs in a new emotional context, the variation often charts character development; the same rain now feels different because she has changed. The shift is purposeful rather than careless, nothing points to the friend\'s sadness, and a recurring element placed at key moments carries meaning.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'A concrete object that carries abstract significance in a story is a', options: ['theme', 'symbol', 'setting', 'conflict'], correctAnswer: 1, explanation: 'A symbol is a concrete element that stands for something beyond itself. A theme is an abstract insight, setting is time and place, and conflict is a struggle between forces.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'How does a symbol typically gain its meaning in fiction?', options: ['Through the contexts and moments where it appears', 'Through a dictionary definition of the object itself', 'Through the author\'s explanation in the first line', 'Through the reader\'s personal memories alone'], correctAnswer: 0, explanation: 'Symbols accumulate meaning from where and how they appear in the text. A dictionary gives literal meaning, authors rarely explain their symbols, and personal associations must be tested against the text.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'Read the passage: “Every spring, Grandfather pruned the pear tree hard, saying it would bear better for the cutting. The year after his stroke, no one pruned it, and it grew wild and gave no fruit.” What does the pear tree most suggest?', options: ['The family wanted to cut the pear tree down for good', 'The family has moved away from Grandfather\'s farm', 'Pear trees cannot survive cold winters without care', 'Growth depends on the discipline he once provided'], correctAnswer: 3, explanation: 'The tree\'s fate tracks the grandfather\'s role: his hard pruning made it fruitful, and without him it runs wild and barren, suggesting the family\'s loss of his guiding discipline. No one wants it cut down, nothing says the family moved, and the passage concerns pruning rather than winter.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'A novel\'s opening and closing scenes both feature a lighthouse; in the first its beam is described as “watchful,” in the last as “indifferent.” Which claim best accounts for this pattern?', options: ['The lighthouse was replaced between the novel\'s first and final scenes', 'The author describes the same lighthouse mainly to establish the setting', 'The symbol\'s shifting portrayal charts the protagonist\'s loss of faith', 'The change shows that lighthouses are traditional symbols of guidance'], correctAnswer: 2, explanation: 'When the same symbol is described differently at the start and end, the change usually reflects a change in the perceiver. Nothing suggests a new lighthouse, the loaded adjectives do more than set the scene, and a conventional meaning of guidance cannot explain a beam described as indifferent.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'How do symbol and motif typically relate?', options: ['A symbol must recur often, but a motif appears once', 'A motif is one object, and a symbol is a repeated idea', 'They are unrelated devices that do not overlap', 'A motif can be a recurring symbol whose meaning builds'], correctAnswer: 3, explanation: 'A motif is defined by recurrence, and a symbol that returns throughout a work can function as a motif. The first two options reverse the definitions, and the two devices overlap frequently.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'After his father\'s death, a character keeps his father\'s broken compass and later says he no longer knows what to do with his life. The compass most likely suggests', options: ['a love of travel', 'a loss of direction', 'a fear of the sea', 'a skill with tools'], correctAnswer: 1, explanation: 'A compass gives direction, and a broken one paired with his confession suggests he feels lost without his father. Nothing in the details concerns travel, the sea, or mechanical skill.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'In a novel, a locked piano first represents a mother\'s abandoned ambitions; in the final chapter, her daughter unlocks it and plays. How has the symbol developed?', options: ['It continues to represent the mother\'s failed hopes', 'It shows that the piano was not really locked before', 'It now suggests a dream reclaimed by her daughter', 'It reveals the daughter\'s dislike of her mother'], correctAnswer: 2, explanation: 'Symbols can evolve; unlocking and playing the piano turns a sign of abandonment into one of renewal. The final scene changes the symbol\'s meaning rather than repeating it, the lock was real, and playing her mother\'s piano suggests connection rather than dislike.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'A recurring image of birds runs through a story: caged in the first chapter, flying overhead in the fifth, and dead on the doorstep in the final scene. Which interpretation best accounts for the whole pattern?', options: ['Hope for freedom rises, then collapses by the end', 'The birds only show that the story is set in the countryside', 'The final dead bird erases the meaning of the earlier birds', 'Each bird image is separate and unrelated to the others'], correctAnswer: 0, explanation: 'Tracking a motif across the whole text reveals an arc, here from confinement to brief freedom to death. The images do more than mark a rural setting, the ending completes rather than erases the pattern, and the repetition links the images.', difficulty: 'hard', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'In a story, a family portrait cracks when the father throws a glass; the mother rehangs it, crack and all, and seats guests so that they cannot see it. Which thesis best analyzes the portrait as a symbol?', options: ['The cracked portrait stands for the father\'s guilt, which drives him to change by the story\'s end.', 'The portrait cracks when the father throws a glass, and the mother hangs it back in the hallway.', 'Rehung but left unrepaired, the cracked portrait embodies a family that hides damage instead of healing it.', 'Rehanging the portrait shows the mother\'s pride in her family\'s honesty about its troubles.'], correctAnswer: 2, explanation: 'A strong thesis interprets what a symbol means in its specific context: the crack is kept but hidden from guests, just as the family conceals its damage. The story shows no change in the father, retelling how the portrait cracked is summary, and seating guests so they cannot see the crack contradicts any claim of honesty.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'A student argues that a recurring river represents the passage of time. Which evidence best supports this claim?', options: ['Each chapter opens with the river in a new season', 'The river is wide and full of fish in the summer', 'The family\'s house sits on the river\'s east bank', 'The river is named after the town\'s first settler'], correctAnswer: 0, explanation: 'Showing the river at the start of each chapter in changing seasons links it to time\'s movement. The fish, the house\'s location, and the river\'s name describe the river but do not connect it to time.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  { question: 'A recurring element that gathers significance through repetition in a work is a', options: ['climax', 'motif', 'foil', 'flashback'], correctAnswer: 1, explanation: 'A motif is a recurring image, idea, or object whose repetition builds meaning. The climax is the point of greatest tension, a foil is a contrasting character, and a flashback is a scene from an earlier time.', difficulty: 'easy', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 1, part: 1 },
  { question: 'A narrative in which characters and events consistently stand for abstract ideas, such as Greed or Faith, is', options: ['a parody', 'an elegy', 'an epic', 'an allegory'], correctAnswer: 3, explanation: 'An allegory sustains a system of symbolic correspondence across a whole narrative. A parody imitates in order to mock, an elegy mourns the dead, and an epic narrates heroic deeds on a grand scale.', difficulty: 'medium', domain: 'figurative-language', topicSlug: 'englit-symbol-motif-fiction', formSet: 2, part: 1 },
  // ── Domain: analysis-argument ───────────────────────────
  // englit-plot-conflict-theme
  { question: 'In literary analysis, plot is best described as', options: ['a list of random events in the story', 'a causally linked chain of events', 'the central message about human life', 'the time and place where events occur'], correctAnswer: 1, explanation: 'Plot is the causal arrangement of events, in which each event leads to consequences that produce meaning. Random events lack causation, the central message is theme, and time and place are setting.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'Which statement expresses a literary theme rather than a moral cliché?', options: ['Always be loyal to the people that you love the most', 'Honesty is the best policy in every situation in life', 'Never trust strangers, no matter how kind they seem', 'Loyalty can trap us once it outlasts its reasons'], correctAnswer: 3, explanation: 'A theme is a nuanced insight grounded in a work\'s pattern, not a slogan or command. The other statements are prescriptive morals stated in absolute terms, which AP readers treat as reductive.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'In a story, a farmer battles a flood while also struggling over whether to sell land his family has worked for generations. How do the two conflicts work together?', options: ['The external flood forces a hard decision about his inner loyalty', 'The flood settles his inner conflict by destroying the land', 'The two conflicts are unrelated and could be told separately', 'The inner conflict distracts from the flood\'s main tension'], correctAnswer: 0, explanation: 'External and internal conflicts often intensify each other; the flood makes the question of keeping the land urgent. The flood raises the stakes rather than settling the question, the conflicts are linked, and the inner struggle gives the flood its meaning.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'A story describes a son\'s success just before readers learn how his father sacrificed to make it possible. How does this ordering shape theme?', options: ['It shows that the son achieved success entirely alone', 'It reduces the father to a minor figure in the story', 'It recasts success as a debt to unseen sacrifice', 'It keeps the father\'s sacrifice hidden from readers'], correctAnswer: 2, explanation: 'Event ordering creates emphasis; placing the revelation after the success forces readers to reconsider it. The revelation undercuts the idea of individual achievement, it makes the father central, and readers do learn of the sacrifice.', difficulty: 'hard', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'Which sequence correctly orders the traditional elements of plot?', options: ['exposition, climax, rising action, falling action, resolution', 'exposition, rising action, climax, falling action, resolution', 'rising action, exposition, climax, resolution, falling action', 'exposition, falling action, rising action, climax, resolution'], correctAnswer: 1, explanation: 'The traditional arc moves from exposition through rising action to the climax, then through falling action to the resolution. The other sequences place the climax before the rising action, open with rising action, or put falling action before the climax.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'How does conflict typically lead readers to a work\'s theme?', options: ['Conflict names the theme directly at the story\'s climax', 'Conflict matters mainly when it ends in physical violence', 'Conflict entertains readers but carries little meaning', 'Characters\' risks and choices reveal the work\'s values'], correctAnswer: 3, explanation: 'Conflict reveals values and stakes, so the choices characters make under pressure point to theme. Themes are seldom named outright, conflict need not be violent, and conflict is a primary pathway to meaning.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'Read the passage: “Each morning Lena took the long way to school to avoid the corner where the older boys waited. On the day her brother left for the army, she walked straight past them.” What does the final sentence most suggest?', options: ['His departure has given her new resolve', 'The older boys have moved to a different corner', 'Lena was running late and had no time to detour', 'The boys had been warned to leave her be'], correctAnswer: 0, explanation: 'Placing her first act of courage on the day her brother leaves implies that his absence pushes her to face what she avoided. The boys are still there, nothing mentions lateness, and no warning from the brother is described.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'A woman finally confronts her controlling sister, but the story ends with her apologizing and returning home. Which theme is best supported?', options: ['Confronting family brings lasting freedom and peace', 'Sisters are naturally kinder to one another than others', 'Old family roles can win out even after defiance', 'Apologizing is the best way to resolve family conflict'], correctAnswer: 2, explanation: 'The arc from confrontation to apology suggests how hard established roles are to escape. The ending contradicts lasting freedom, nothing compares sisters with other people, and an apology that restores control is not presented as the best way to resolve family conflict.', difficulty: 'hard', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'How do plot structure and theme connect?', options: ['Theme is fixed before the plot and unaffected by it', 'The order of events directs what ideas readers emphasize', 'Plot structure matters mainly in mystery and detective fiction', 'Theme comes from the title, and plot from the characters'], correctAnswer: 1, explanation: 'How events are arranged, including what is revealed first and what is delayed, shapes which ideas carry weight. Theme emerges through plot rather than independently, structure matters in all fiction, and titles rarely determine theme.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'A character\'s struggle against a blizzard is best classified as', options: ['character versus self', 'character versus society', 'character versus character', 'character versus nature'], correctAnswer: 3, explanation: 'Struggles against storms, wilderness, or other natural forces are character versus nature. Character versus self is internal, versus society involves social institutions, and versus character involves another person.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'A girl\'s conflict with her strict grandmother escalates across a story until a fire forces them to rescue each other. How does the climax change the conflict?', options: ['The fire ends the story before the conflict can change', 'The climax proves the grandmother was right from the start', 'Shared danger turns rivalry into mutual dependence', 'The fire introduces a new conflict unrelated to them'], correctAnswer: 2, explanation: 'A climax often transforms the central conflict; needing each other to survive recasts their rivalry. The rescue itself is the change, it does not vindicate either side, and the fire bears directly on their relationship.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'A novel ends with the protagonist winning the lawsuit she has fought for years, then sitting alone in an empty courtroom. What is the most defensible thematic reading?', options: ['Victory can cost the very connections that made it matter', 'Justice is worth whatever sacrifice a person makes', 'The lawsuit was unimportant to the protagonist', 'The protagonist lost the case despite the ruling'], correctAnswer: 0, explanation: 'The image of solitude after victory suggests the struggle consumed her relationships, complicating the win. The ending questions rather than affirms that any cost is worth it, her years of effort show the case mattered, and she did win.', difficulty: 'hard', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'Two brothers feud over their late father\'s boat; neither will mention the father, and at the end the older brother sits alone in the boat and weeps. Which thesis best states a theme for an AP prose fiction essay?', options: ['Two brothers feud over their late father\'s boat until the older one breaks down in it alone.', 'The story teaches that brothers should put family before possessions when a parent dies.', 'The boat stands for the father\'s wealth, and the feud is mainly a dispute over its value.', 'The brothers\' feud over the boat reveals how pride can disguise grief as anger.'], correctAnswer: 3, explanation: 'A strong thesis interprets the conflict and states an insight about people: the brothers\' silence about their father and the final weeping show grief hiding inside the feud. Retelling the feud is summary, a moral lesson reduces the story to advice, and nothing in the story suggests the boat\'s money value is at stake.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'A student argues that a story\'s conflict shows how poverty limits choice. Which evidence best supports this claim?', options: ['Ana and her mother argue about chores in the kitchen', 'Ana turns down college to keep the family\'s rent paid', 'Ana\'s apartment building has a broken front elevator', 'Ana wins a spelling contest at her school in the spring'], correctAnswer: 1, explanation: 'Giving up college for rent shows economic need directly constraining a major choice. Arguments about chores, a broken elevator, and a spelling contest do not show poverty limiting her options.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  { question: 'The point of highest tension, where the central conflict reaches its turning point, is the', options: ['climax', 'exposition', 'resolution', 'rising action'], correctAnswer: 0, explanation: 'The climax is the peak of tension where the conflict turns. Exposition comes first, rising action builds toward the climax, and the resolution follows it.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 1, part: 1 },
  { question: 'On the AP literary argument essay, a strong thesis about theme should be', options: ['a restatement of the prompt\'s wording with no position', 'a one-word subject such as love, war, or ambition', 'a defensible interpretation that evidence can support', 'a summary of the chosen work\'s major plot events'], correctAnswer: 2, explanation: 'The rubric\'s thesis row rewards a defensible interpretation that responds to the prompt. Restating the prompt takes no position, a one-word subject is a topic rather than a claim, and plot summary is not an argument.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-plot-conflict-theme', formSet: 2, part: 1 },
  // englit-social-commentary-drama
  { question: 'Satire is best described as', options: ['critique of folly through irony or exaggeration', 'lighthearted humor that has no critical purpose', 'a sincere tribute to a society\'s admired leaders', 'a factual report on current social conditions'], correctAnswer: 0, explanation: 'Satire uses irony, exaggeration, or ridicule to expose and criticize folly or injustice, often seriously despite its comic methods. Humor without critique is not satire, sincere tribute is the opposite of its purpose, and a factual report lacks its ironic method.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'In a satirical play, a mayor solves homelessness by banning the word “homeless” from public documents. What is the satire\'s main target?', options: ['Homeless people who refuse available assistance', 'Dictionaries that fail to keep up with language', 'Citizens who complain too much about the mayor', 'Officials who manage appearances, not problems'], correctAnswer: 3, explanation: 'The absurd policy exaggerates a real tendency to treat problems by renaming them, exposing officials who care about appearances. The joke is on the mayor rather than on homeless people, dictionaries, or complaining citizens.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'In a play, a factory owner remains seated while his workers stand, and he interrupts whenever they speak. What do these staging choices most reveal?', options: ['The owner\'s poor health and his need to rest often', 'The hierarchy that governs whose voice counts', 'The workers\' lack of interest in the meeting itself', 'The play\'s setting in an earlier historical era'], correctAnswer: 1, explanation: 'Power dynamics show in who controls speech, space, and posture; sitting while others stand and cutting them off stage his dominance. Nothing mentions illness, the workers are trying to speak rather than disengaging, and the staging concerns power rather than period.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'A politician in a play delivers a speech praising family values, then, in the next scene, ignores his daughter\'s call for help. What does this juxtaposition most expose?', options: ['The daughter\'s exaggerated need for her father\'s attention', 'The politician\'s skill as a convincing public speaker', 'The gap between public performance and private conduct', 'The play\'s support for the politician\'s stated values'], correctAnswer: 2, explanation: 'Juxtaposing a public speech with private neglect stages the tension between social performance and inner reality. The play invites judgment of the father rather than the daughter, his speaking skill is beside the point, and the contrast undercuts rather than supports his stated values.', difficulty: 'hard', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'How does drama often deliver social commentary?', options: ['By listing statistics about social problems', 'By avoiding reference to real institutions', 'By having a narrator state the moral directly', 'By staging social conflict in living scenes'], correctAnswer: 3, explanation: 'Drama critiques institutions and norms by putting them onstage in conflicts audiences watch unfold. Plays rarely rely on statistics, social drama typically engages real institutions, and drama usually lacks a narrator who explains the moral.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'Why might a playwright use satire rather than direct argument to criticize a social practice?', options: ['Satire avoids holding a point of view on the issue', 'Exaggeration exposes the absurdity of the familiar', 'Direct argument is not allowed in dramatic works', 'Satire guarantees that audiences will agree'], correctAnswer: 1, explanation: 'Satire defamiliarizes; by exaggerating what audiences accept as normal, it reveals the absurdity in it. Satire always has a point of view, plays can argue directly, and no technique guarantees agreement.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'In a play, a wealthy hostess says, “We simply adore the poor — we\'ve hired three of them,” while gesturing at her servants. This line is an example of', options: ['sincere praise of the servants', 'a soliloquy about social class', 'verbal irony used for satire', 'dramatic irony about the plot'], correctAnswer: 2, explanation: 'The hostess\'s claim of adoration is undercut by treating people as acquisitions, and the playwright uses that gap to satirize her class. The line is not sincere, she speaks to others rather than alone, and the irony lies in her words rather than in what the audience knows about the plot.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'A play stages a dinner party at which guests discuss charity while a maid silently clears their plates for the entire scene. What does this staging most accomplish?', options: ['The unnoticed maid exposes what the guests\' generosity misses', 'It makes the maid the play\'s narrator figure for the scene', 'It shows the maid as content with her quiet place in the house', 'It confirms that the guests are generous and sincere people'], correctAnswer: 0, explanation: 'Placing unacknowledged labor beside talk of charity lets the staging make the critique without dialogue. A silent figure cannot narrate, nothing in her silence shows contentment rather than invisibility, and the contrast undercuts the guests\' generosity.', difficulty: 'hard', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'In a play, a family\'s patriarch holds the only key to the house, and every scene is set inside that house. How do setting and power interact?', options: ['The house serves mainly as a realistic backdrop for scenes', 'The key is a minor prop with little thematic role in the play', 'The closed house becomes a domain that he alone controls', 'The setting suggests the family is free to leave as they wish'], correctAnswer: 2, explanation: 'Controlling the only key turns the single setting into an instrument of control, so place and power reinforce each other. The setting does more than provide realism, the key is central to the power dynamic, and his control of access implies the family is not free to come and go.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'A character who is gracious at parties but cruel at home illustrates the tension between', options: ['plot and its subplots', 'public and private selves', 'setting and its mood', 'speaker and the poet'], correctAnswer: 1, explanation: 'The gap between social performance and inner reality is the tension between public and private selves. Plot and subplot, setting and mood, and speaker and poet are different pairings that do not describe a hidden self.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'In Act 1, a servant answers only “Yes, sir”; by Act 3, she contradicts her employer in front of his guests. What does this change most suggest?', options: ['A shift in their balance of power', 'The servant has forgotten proper manners', 'The employer has become hard of hearing', 'The guests have asked her to speak up'], correctAnswer: 0, explanation: 'Changes in who speaks and how boldly track changes in power; open contradiction marks the servant\'s new standing. Reading it as forgotten manners trivializes the change, and neither hearing loss nor the guests\' requests appear in the play.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'A social drama ends with the reformer who challenged the town being praised in public and quietly fired in private. What does this ending most suggest about the play\'s critique?', options: ['The reformer\'s ideas were wrong and deserved rejection', 'The town has fully accepted the reformer\'s proposals', 'The play avoids taking any position on the reform', 'Institutions can absorb dissent yet still punish it'], correctAnswer: 3, explanation: 'The split between public praise and private punishment exposes how institutions neutralize critics while appearing open. The firing does not prove the ideas wrong, it shows the proposals were not accepted, and the pointed ending takes a clear position.', difficulty: 'hard', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'In a play about a rent dispute, the landlord speaks only in legal jargon while his tenants speak plainly about cold rooms and broken locks. Which thesis best analyzes the play\'s social commentary?', options: ['The play stages a rent dispute between a landlord who speaks in legal terms and his tenants.', 'By giving the landlord only legal jargon, the play shows how law can shield exploitation.', 'The landlord\'s legal jargon shows that the play admires his education and his precision.', 'The tenants\' plain speech shows they are less educated, which is why they lose the dispute.'], correctAnswer: 1, explanation: 'A strong thesis links a dramatic choice to a specific critique: the jargon lets the landlord talk past cold rooms and broken locks. Describing the dispute is summary, admiration for his precision misreads a contrast that favors the tenants\' concrete complaints, and the play gives no outcome that would show the tenants losing.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'A student argues that a play critiques gender roles. Which evidence best supports this claim?', options: ['The wife and her husband live in a large house in the suburbs', 'The wife wears an elegant dress to the dinner party in Act 2', 'The husband works long hours at an office downtown each day', 'The wife\'s plan is praised only once her husband presents it'], correctAnswer: 3, explanation: 'The same idea receiving praise only from the husband shows gender, not merit, determining whose ideas count. The house, the dress, and the husband\'s hours do not reveal any critique of gender roles.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },
  { question: 'Humorous imitation of a work or style in order to mock it is called', options: ['parody', 'elegy', 'tragedy', 'allegory'], correctAnswer: 0, explanation: 'Parody imitates a recognizable work or style to ridicule it. An elegy mourns, a tragedy dramatizes a downfall, and an allegory uses characters and events to stand for abstract ideas.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 1, part: 1 },
  { question: 'A satirical work that pretends to praise what it actually condemns relies most on', options: ['meter', 'flashback', 'irony', 'foreshadowing'], correctAnswer: 2, explanation: 'Praising what one condemns is a gap between stated and intended meaning, which is irony. Meter is a rhythmic pattern, and flashback and foreshadowing are ways of handling time.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-social-commentary-drama', formSet: 2, part: 1 },

  // ── englit-essay-writing (analysis-argument) ──
  { question: 'A student has 120 minutes for the AP English Literature free-response section. Which plan best fits the section?', options: ['About 40 minutes on each of three essays: poetry, prose and argument', 'About 60 minutes on each of two essays: poetry and prose', 'About 40 minutes on each of three essays: poetry, drama and synthesis', 'About 30 minutes on each of four essays, including a short answer'], correctAnswer: 0, explanation: 'The section has three essays, poetry analysis, prose fiction analysis and literary argument, so about 40 minutes each is the right budget. There are not two or four essays, and synthesis is an English Language task rather than a Literature one.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 1 },
  { question: 'An essay quotes well-chosen lines and explains how each one supports the writer\'s claim. Which rubric row does this work mainly serve?', options: ['Thesis, which is worth up to 4 points', 'Evidence and Commentary, worth up to 2 points', 'Evidence and Commentary, worth up to 3 points', 'Evidence and Commentary, which is worth up to 4 points'], correctAnswer: 3, explanation: 'Quoting and explaining evidence is Row B, Evidence and Commentary, which carries 4 of the rubric\'s 6 points. The thesis row is worth only 1 point and rewards a defensible claim, and Row B is worth 4 points rather than 2 or 3.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 1 },
  { question: 'A prose passage shows a father teaching his daughter to swim. Which statement would best earn the thesis point?', options: ['The father\'s patient instructions voice a love he cannot say aloud.', 'The author uses imagery, dialogue and syntax to show their relationship in the passage.', 'The passage describes a father teaching his daughter to swim at a lake one summer.', 'In the passage the father teaches his daughter, and by the end the daughter learns to swim.'], correctAnswer: 0, explanation: 'A defensible thesis makes an arguable claim about meaning, here that the swimming lesson expresses an unspoken love. Describing the scene and retelling the outcome are summary, and listing devices names techniques without claiming anything about what they mean.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 2 },
  { question: 'A student drafts, “Through repeated images of locked doors, the passage makes the house feel like a trap.” What would most strengthen this into a thesis?', options: ['Adding a list of the other devices found in the passage', 'Replacing “trap” with a more formal literary term', 'Dropping the images so the claim is about the plot alone', 'Adding what the trap reveals, such as the heroine\'s stifled ambition'], correctAnswer: 3, explanation: 'The draft has a technique and an effect but stops before the “so what”; adding what the trap reveals about the character turns an observation into an argument. More devices, plot alone or fancier wording would not supply a claim about meaning.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 2 },
  { question: 'Which statement could NOT serve as a defensible thesis, because no reasonable reader would dispute it?', options: ['The novel is set in a small farming town during a drought.', 'The family\'s pride, not the drought, is what finally ruins it.', 'The drought mirrors the slow failure of the parents\' marriage.', 'The drought exposes the town\'s cruelty more than it causes it.'], correctAnswer: 0, explanation: 'A thesis must be arguable, and the setting of the novel is a plain fact that no reader would contest. Each of the other statements makes an interpretive claim about the drought\'s meaning that a classmate could reasonably argue against.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 2 },
  { question: 'A student is writing about a widowed character\'s loneliness. Which piece of evidence would be most useful?', options: ['the narrator\'s note that the story is “set in a quiet town”', 'the narrator\'s note that it was “a Tuesday in early March”', 'the narrator\'s note that she has lived there “for many years”', 'the narrator\'s note that she sets out “a single cup and plate”'], correctAnswer: 3, explanation: 'Specific, analyzable evidence lets the writer say something: the single cup and plate make her solitude concrete and habitual. The town\'s quiet, her years there and the date are details that offer little to interpret about loneliness.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 3 },
  { question: 'Read this excerpt from a student\'s body paragraph:\n“The mother is worried. ‘She checked the lock three times.’ Then she went to bed.”\nWhat is the main problem with how the evidence is used?', options: ['The quote is too short to count as specific evidence', 'The quote should have been paraphrased, not quoted', 'The quote is dropped in with no setup or explanation', 'The writer has quoted too many lines from the text'], correctAnswer: 2, explanation: 'This is a hit-and-run quotation: it stands alone as its own sentence and is followed by plot rather than commentary, so it earns little credit. Its brevity is fine, quoting exactly is better than paraphrasing, and only one line is quoted.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 3 },
  { question: 'A student plans a body paragraph with seven quotations and one sentence of explanation. What is the best advice?', options: ['Add more quotations so the evidence looks thorough', 'Cut the explanation so that the quotes speak for themselves', 'Keep the strongest one or two quotes and explain each one fully', 'Paraphrase every quotation so the paragraph is shorter'], correctAnswer: 2, explanation: 'The rubric rewards well-chosen evidence that is fully explained, so a few rich quotes with real commentary beat a pile of quotes. Adding quotes or removing the explanation makes the problem worse, and paraphrasing does not supply any reasoning.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 3 },
  { question: 'After quoting the line “the house held its breath,” which follow-up is genuine commentary rather than paraphrase?', options: ['Personifying the house makes the family seem frozen in dread of what comes next.', 'In other words, the house was silent, like a person who is holding their breath.', 'This means the house was very quiet, as though it had stopped breathing for a while.', 'The author chose to say that the house held its breath instead of saying it was quiet.'], correctAnswer: 0, explanation: 'Commentary interprets an effect and links it to meaning: the personification spreads the family\'s suspense into the house itself. The other follow-ups restate the image in plainer words or merely note the author\'s choice without saying what it does.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 4 },
  { question: 'Which best describes the line of reasoning needed for the top score in the Evidence and Commentary row?', options: ['Body paragraphs whose claims build to develop the thesis', 'Body paragraphs that each restate the thesis at the start', 'Body paragraphs that each identify a different device in turn', 'An essay that quotes the text in every sentence of the body'], correctAnswer: 0, explanation: 'A line of reasoning is a set of connected claims that build on one another and keep developing the thesis. A device-by-device hunt produces disconnected observations, restating the thesis in each paragraph does not develop it, and constant quotation leaves no room for reasoning.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 4 },
  { question: 'In a passage, the narrator calls a family\'s new house “a showroom.” Which follow-up turns this evidence into commentary?', options: ['The narrator says the house is like a showroom, which means it is clean.', 'This quote shows that the narrator thinks the house looks just like a showroom.', 'The word “showroom” is a metaphor, a comparison without “like” or “as.”', '“Showroom” makes the home a display, hinting at a deeper emptiness inside.'], correctAnswer: 3, explanation: 'The commentary interprets the word\'s connotation, a place for display rather than living, and connects it to a meaning: an emptiness beneath the family\'s polished surface. The other follow-ups paraphrase the quote, repeat it or define the device without explaining any effect.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 4 },
  { question: 'Why is organizing a poetry essay around the poem\'s shift, or volta, often effective?', options: ['It lets the writer skip the lines that come before the turn', 'Readers award an extra point for naming the volta correctly', 'The poem\'s own turn hands the essay a ready-made line of reasoning', 'It allows the essay to avoid quoting the poem directly'], correctAnswer: 2, explanation: 'Building the essay around what changes before and after the turn lets the poem\'s structure carry the argument, which produces a connected line of reasoning. The lines before the turn still need analysis, no point is given for labeling a volta, and the essay still needs quoted evidence.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 5 },
  { question: 'In a poetry essay, a student writes, “The poem\'s tone makes me feel uneasy.” What confusion does this sentence show?', options: ['Tone refers only to rhythm, so it cannot create unease', 'Mood is the speaker\'s attitude, so it should replace tone', 'Tone is the speaker\'s attitude, so unease is mood', 'Tone belongs only to prose, so it does not apply to poems'], correctAnswer: 2, explanation: 'Tone is the speaker\'s attitude toward the subject, and the feeling produced in the reader is mood, so the reader\'s unease should be called mood. Tone is not rhythm, mood belongs to the reader rather than the speaker, and poems have tone just as prose does.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 5 },
  { question: 'A poem\'s first three stanzas describe a ruined garden; the fourth begins, “Still, each spring . . .” In an essay, the word “Still” is best treated as', options: ['a continuation of the ruin that needs no comment', 'a change of speaker that the essay should name', 'a rhyme pattern that the essay should label', 'a turn to endurance the essay should explain'], correctAnswer: 3, explanation: 'Pivot words such as “still” and “yet” often mark the poem\'s turn, and the essay should explain what the shift toward endurance does to meaning. The word reverses rather than continues the ruin, nothing signals a new speaker, and it is not a rhyme.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 5 },
  { question: 'A passage never states that a character is generous, but shows him quietly paying a stranger\'s bill and slipping away. This technique is', options: ['direct characterization', 'indirect characterization', 'dramatic irony', 'omniscient narration'], correctAnswer: 1, explanation: 'Revealing a trait through a character\'s actions, rather than stating it, is indirect characterization. Direct characterization would simply tell the reader he is generous, dramatic irony requires the reader to know something a character does not, and the scene does not depend on who narrates.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 6 },
  { question: 'A student has prepared Hamlet for the literary argument essay. The prompt asks how a character torn between duty and desire contributes to the meaning of the work as a whole. The best approach is to', options: ['argue a claim about Hamlet that answers this specific prompt', 'write a full plot summary of Hamlet to show strong recall', 'write about a theme of Hamlet that the prompt does not raise', 'list every character in Hamlet and describe each one in turn'], correctAnswer: 0, explanation: 'The literary argument rewards bending a well-known work to the actual prompt with a defensible claim and specific evidence from memory. Plot summary is the most common failure, ignoring the prompt costs the thesis point, and a character list makes no argument.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 6 },
  { question: 'What does the student write about on the AP English Literature literary argument essay (Question 3)?', options: ['The poem printed in the exam booklet for the first essay', 'A novel or play from the student\'s reading or the list', 'A nonfiction essay or speech that the student knows well', 'A passage printed with the prompt, analyzed line by line'], correctAnswer: 1, explanation: 'Question 3 gives a thematic prompt and asks the student to choose a work of fiction, such as a novel or play, from their own reading or the list provided, and argue from memory. The printed poem and printed prose passage belong to Questions 1 and 2, and nonfiction is not what the prompt asks for.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 6 },
  { question: 'An essay with a strong thesis and solid analysis ends, “This shows that the story is about the human condition.” Does that sentence earn the sophistication point?', options: ['Yes, because it links the story to a broad, universal theme', 'No, because sophistication must be shown throughout', 'Yes, but only half the point, since it appears at the end', 'No, because sophistication is earned only in the thesis'], correctAnswer: 1, explanation: 'Row C rewards complex understanding demonstrated throughout the essay; a grand closing phrase announces significance without showing it. The point is all or nothing, so there is no half credit, and it is not limited to the thesis.', difficulty: 'medium', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 7 },
  { question: 'With about 40 minutes for one essay, how should a student spend the first several minutes?', options: ['Writing the conclusion first so it is not forgotten', 'Drafting body paragraphs before choosing a thesis', 'Copying out key quotations in full before reading', 'Reading closely, annotating and planning a thesis'], correctAnswer: 3, explanation: 'A strong plan spends the opening minutes reading closely, marking key evidence and the shift, and settling on a thesis with two or three points. Writing the conclusion first or drafting without a thesis undermines the line of reasoning, and copying quotations wastes time.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 1, part: 7 },
  { question: 'A student has 10 minutes left and has not started the third essay. What is the best choice?', options: ['Leave it blank and polish the first two essays instead', 'Write a quick thesis and paragraph rather than nothing', 'Spend the time rereading the first essay\'s thesis', 'Write only an outline, which is scored like a full essay'], correctAnswer: 1, explanation: 'A rushed essay with a defensible thesis and some evidence can still earn points, while a blank one earns none, so the student should write something for every essay. Polishing or rereading earlier work gains little, and an outline is not scored as a full essay.', difficulty: 'easy', domain: 'analysis-argument', topicSlug: 'englit-essay-writing', formSet: 2, part: 7 },

  // ── englit-prose-style-analysis (short-fiction) ──
  { question: 'Compare two sentences.\nA: “The rain fell on the town.”\nB: “The rain hammered the town\'s tin roofs all night, relentless as a debt collector.”\nCompared with sentence A, sentence B chiefly', options: ['reports more facts about the weather in a neutral, objective way', 'uses a charged verb and a simile to make the rain feel oppressive', 'shifts the narration from the third person into the first person', 'uses a periodic structure that withholds its main clause to the end'], correctAnswer: 1, explanation: 'Style is a set of choices: “hammered” is a violent verb and “relentless as a debt collector” is a simile, so the rain becomes something that oppresses the town. Sentence B is less neutral, not more, there is no first-person narrator, and its main clause comes first rather than last.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 1 },
  { question: 'A student\'s draft says, “The author uses a lot of imagery.” Which revision best turns this identification into analysis?', options: ['The author uses visual, auditory and tactile imagery throughout the passage', 'The imagery appears in the second paragraph and again in the final lines', 'The author is very skilled at using imagery to describe the old house', 'The rust and peeling paint make the family\'s pride seem already in decay'], correctAnswer: 3, explanation: 'Analysis ties a specific choice to an effect or meaning, and the revision about rust and peeling paint links concrete images to the decay of the family\'s pride. Listing the senses, locating the images and praising the author all name or point to imagery without saying what it does.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 1 },
  { question: 'Read the sentence:\n“The landlord counted the coins twice, his thin fingers lingering on each one, and at last pronounced the rent ‘adequate.’”\nThe diction “lingering” and “adequate” most suggests that the landlord is', options: ['grudging and greedy even though he has been paid', 'careless about the amount of money he collects', 'generous toward a tenant who has struggled to pay', 'nervous that some of the coins may be counterfeit'], correctAnswer: 0, explanation: 'Fingers that linger over each coin suggest a reluctance to let money go, and calling full payment merely “adequate” withholds any thanks, so the connotations build a grudging, greedy figure. Nothing signals generosity, counting twice is the opposite of carelessness, and the passage gives no hint of counterfeit money.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 2 },
  { question: 'A narrator could describe a character who spends little money as “thrifty” or as “miserly.” Choosing “miserly” instead of “thrifty” chiefly', options: ['changes the literal meaning of the description', 'adds a negative judgment through connotation', 'makes the diction more formal and elevated', 'shifts the passage into the second person'], correctAnswer: 1, explanation: 'Both words denote spending little, but “miserly” connotes stinginess and selfishness while “thrifty” connotes prudence, so the choice passes judgment on the character. The denotation stays roughly the same, the two words are equally formal, and word choice alone does not change the point of view.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 2 },
  { question: 'A narrator describes a starving child as follows:\n“The subject exhibited a marked reduction in body mass over the observation period.”\nThe diction is best described as', options: ['colloquial and casual, making the scene feel relaxed', 'clinical and detached, making the suffering feel cold', 'archaic and elevated, lending the scene a grandeur', 'sentimental and charged, heightening pity directly'], correctAnswer: 1, explanation: 'Words like “subject,” “exhibited” and “observation period” come from a laboratory report, so the clinical, detached diction treats a starving child as data, which makes the suffering feel coldly distant. The words are not casual, old-fashioned or emotionally loaded.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 2 },
  { question: 'Read the opening of Charles Dickens\'s A Tale of Two Cities (1859):\n“It was the best of times, it was the worst of times, it was the age of wisdom, it was the age of foolishness, it was the epoch of belief, it was the epoch of incredulity . . .”\nThe repeated structure of these clauses chiefly works to', options: ['slow the narrative so it can describe one setting in detail', 'reveal the narrator\'s personal confusion about the dates', 'present the era as a time of sharp contradictions', 'build suspense by withholding the main clause'], correctAnswer: 2, explanation: 'The anaphora of “it was” and the parallel pairs of opposites set best against worst and wisdom against foolishness, so the era is defined by its contradictions. The clauses name no setting in detail, the narrator is in control rather than confused, and each clause is complete rather than withholding a main idea.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 3 },
  { question: 'Read the sentence:\n“She packed and swept and scrubbed and packed again, and still the house was not ready.”\nThe repeated “and” is an example of', options: ['polysyndeton, which makes her labor feel relentless', 'anaphora, which stresses the first word of each clause', 'asyndeton, which speeds the sentence into a blur', 'a periodic sentence, which delays its main idea'], correctAnswer: 0, explanation: 'Piling up conjunctions is polysyndeton, and each added “and” makes the chores feel endless and heavy. Asyndeton is the opposite, dropping conjunctions, anaphora repeats words at the start of clauses, and the sentence states its main action first rather than delaying it.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 3 },
  { question: 'Read the passage:\n“For three hours the delegates argued, amended, recessed, returned and argued again, each speech longer than the last, each vote postponed until the next. Nobody won.”\nThe final sentence chiefly', options: ['cuts off the long debate with a blunt verdict', 'introduces a new speaker who settles the dispute', 'slows the pace to linger over the debate\'s details', 'shifts the passage from the past into the present'], correctAnswer: 0, explanation: 'After a long, winding sentence that mimics the endless debate, the two-word sentence breaks the rhythm and lands like a blunt verdict, exposing the debate as pointless. It introduces no speaker, it speeds up rather than slows the pace, and it stays in the past tense.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 3 },
  { question: 'Read the sentence:\n“Through the long winter, past the failed harvest and the empty storehouse and the slow departure of every neighbor she had known, she stayed.”\nThe sentence withholds its main clause until the end chiefly in order to', options: ['list the reasons she was finally forced to leave', 'show that the narrator is unsure what she chose', 'make her decision to stay land with climactic force', 'hurry the reader past a minor, unimportant detail'], correctAnswer: 2, explanation: 'This is a periodic sentence: the hardships pile up first, so the short main clause “she stayed” arrives as a climax that stresses her endurance. The hardships are reasons to leave, but she does not leave, the narrator states her choice plainly, and delaying the clause slows the reader rather than hurrying past it.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 3 },
  { question: 'A narrator calls a cruel schoolmaster “that tireless guardian of discipline, who never once let a child\'s tears interrupt a lesson.” The narrator\'s tone toward the schoolmaster is best described as', options: ['reverent', 'nostalgic', 'detached', 'sardonic'], correctAnswer: 3, explanation: 'The praise is mock-praise: celebrating a teacher for ignoring children\'s tears exposes his cruelty, so the tone is sardonic, grimly mocking. A reverent tone would honor him sincerely, nothing longs for the past, and the pointed irony is far from detached.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 4 },
  { question: 'Throughout a story, a clerk\'s office is described through dust on the ledgers, a clock that has stopped and calendars yellowed by years. This pattern of imagery most likely', options: ['shows off the firm\'s wealth and its fine taste', 'establishes that the story is set in the distant past', 'mirrors the stagnation of his working life', 'suggests that time passes quickly in his busy office'], correctAnswer: 2, explanation: 'A recurring pattern of images of dust and stopped time points to theme: the office becomes a picture of a life that has stopped moving. Dust and yellowing do not suggest fine taste or speed, and the details describe neglect in the present rather than placing the story in an earlier era.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 4 },
  { question: 'Read the opening of Charles Dickens\'s Bleak House (1853):\n“Fog everywhere. Fog up the river, where it flows among green aits and meadows; fog down the river, where it rolls defiled among the tiers of shipping and the waterside pollutions of a great (and dirty) city.”\nThe repetition of “fog” together with words like “defiled” and “pollutions” chiefly creates', options: ['an atmosphere of murk that taints the whole city', 'a nostalgic memory of the green countryside', 'a cheerful view of the river\'s busy commerce', 'a calm and clear picture of a peaceful morning'], correctAnswer: 0, explanation: 'The fog is everywhere, up and down the river, and the diction of defilement and pollution makes it a grimy presence that spreads over the city, an oppressive mood. The shipping is described as polluted rather than cheerful, the meadows are passed through rather than longed for, and fog is the opposite of clarity.', difficulty: 'hard', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 4 },
  { question: 'Read the first sentence of Jane Austen\'s Pride and Prejudice (1813):\n“It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.”\nThe narrator\'s claim is best read as', options: ['sincere, since the novel argues that rich men must marry', 'ironic, since it voices what families with daughters wish', 'objective, since it reports a fact accepted by everyone', 'nostalgic, since it longs for older marriage customs'], correctAnswer: 1, explanation: 'The grand phrase “a truth universally acknowledged” is verbal irony: the “truth” is really the hope of families eager to marry their daughters to wealthy men, and the gap between statement and meaning gently mocks them. Reading it as sincere or objective misses the irony, and nothing in the sentence looks back to the past.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 5 },
  { question: 'A first-person narrator insists, “I am not a jealous man,” right after describing how he read his brother\'s letters, timed his brother\'s walks and memorized the names of his brother\'s friends. The gap between the claim and the actions most suggests that the narrator is', options: ['omniscient, able to report every character\'s thoughts', 'reliable, reporting events with complete objectivity', 'unreliable, exposing the very feeling he denies', 'second-person, drawing the reader into the action'], correctAnswer: 2, explanation: 'When a narrator\'s own account contradicts his claims, the reader learns to distrust him; the gap exposes the jealousy he denies, which makes him unreliable. He reports only his own actions, his account undercuts his objectivity, and he speaks as “I” rather than addressing “you.”', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 5 },
  { question: 'After a flood destroys his farm and drowns his livestock, a character remarks, “Well, it\'s been a damp spring.” This line is an example of', options: ['understatement', 'hyperbole', 'personification', 'simile'], correctAnswer: 0, explanation: 'Calling a catastrophic flood “a damp spring” deliberately downplays it, which is understatement, and the gap can suggest stoicism or grim humor. Hyperbole exaggerates rather than downplays, nothing nonhuman is given human traits, and there is no comparison using “like” or “as.”', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 5 },
  { question: 'A passage describes a hospital ward at night: lights that flicker, curtains that “whisper” and a wall clock that “ticked as if counting down.” Which thesis best shows how these choices work together?', options: ['The passage describes a hospital ward at night using imagery and personification.', 'The author uses many literary devices, such as imagery, personification and simile.', 'The passage tells the story of a patient who waits all night for the doctor.', 'The unsettling imagery and personified objects make the ward a place of dread.'], correctAnswer: 3, explanation: 'A strong claim shows several choices converging on one effect: flickering light, whispering curtains and a clock counting down all build dread. The other options summarize, list devices without an effect, or retell events, none of which is a defensible interpretation.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 6 },
  { question: 'A student\'s thesis reads, “The author uses diction, syntax and imagery throughout the passage.” The most important revision would be to', options: ['add more device names so that the list is complete', 'state what these choices reveal about the passage', 'retell the events of the passage in the order they occur', 'replace the literary terms with simpler, everyday words'], correctAnswer: 1, explanation: 'The draft names devices without claiming any effect or meaning, the classic vague thesis; adding what the choices reveal makes it defensible. A longer list, a plot summary or plainer wording would still say nothing about meaning.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 6 },
  { question: 'On the AP English Literature prose fiction analysis essay, the sophistication point is most likely earned by', options: ['using as many literary terms as possible', 'writing an essay much longer than average', 'opening with a quotation from another author', 'explaining a tension or shift within the passage'], correctAnswer: 3, explanation: 'Sophistication rewards complex thinking about the passage, such as explaining a tension, a shift or how the parts unify. Piling up terms, writing at length and borrowing an outside quotation do not show a more complex understanding of the text.', difficulty: 'medium', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 2, part: 7 },
  { question: 'Which describes how the AP English Literature prose fiction analysis essay is scored?', options: ['A single holistic score on a scale from 1 to 9', 'Thesis 0–2, evidence and commentary 0–2, sophistication 0–2', 'Thesis 0–1, evidence and commentary 0–3, sophistication 0–2', 'Thesis 0–1, evidence and commentary 0–4, sophistication 0–1'], correctAnswer: 3, explanation: 'The analytic rubric awards up to 6 points: 1 for a defensible thesis, up to 4 for evidence and commentary, and 1 for sophistication, so commentary carries the most weight. The 9-point holistic scale belongs to the old rubric, and the other splits misstate the point values.', difficulty: 'easy', domain: 'short-fiction', topicSlug: 'englit-prose-style-analysis', formSet: 1, part: 7 },

  // ── englit-complex-poetic-analysis (poetry) ──
  { question: 'A poem describes a mother who keeps folding her son\'s shirts long after he has moved away. Which statement reaches the interpretive level, a claim about meaning grounded in the poem\'s technique?', options: ['The mother keeps folding clothes that belong to her son, who has moved away.', 'The mother seems lonely, and the poem suggests that she misses her absent son.', 'The slow, repeated folding turns her grief into a ritual of holding on.', 'The poem has three stanzas and is set in a laundry room on an ordinary afternoon.'], correctAnswer: 2, explanation: 'An interpretive claim connects a technique (the repeated folding) to an effect and a meaning (grief turned into ritual). Restating that she keeps folding his clothes is literal paraphrase, saying she seems lonely is an inference about her feelings with no claim about how the poem makes meaning, and counting stanzas describes structure without any effect.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 1 },
  { question: 'A poet describes the people pouring out of a train station as a “swarm” rather than a “crowd.” The word choice chiefly', options: ['gives the crowd a precise and literal size', 'casts the people as insect-like and faceless', 'suggests the people have gathered to worship', 'makes the scene feel orderly, calm and quiet'], correctAnswer: 1, explanation: 'The two words share a denotation, but “swarm” carries the connotation of insects moving as a mass, so the people lose their individuality. Neither word gives a literal number, nothing suggests worship, and a swarm is disorderly rather than calm.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 1 },
  { question: 'A student\'s notes say, “The poem uses alliteration in line 4.” Applying the “so what?” test, which next step moves the note toward analysis?', options: ['Find two more examples of alliteration elsewhere in the poem', 'Explain what the repeated sounds do to the line and what that suggests', 'Copy a dictionary definition of alliteration into the essay', 'Count the syllables in line 4 to work out the name of its meter'], correctAnswer: 1, explanation: 'Analysis needs technique, effect and meaning, so the student must say what the repeated sounds do and why that matters. More examples, a definition or a syllable count all stay at the level of naming the device, and the exam does not ask students to name meters.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 1 },
  { question: 'Read the line from Gerard Manley Hopkins\'s “God\'s Grandeur” (written 1877):\n“Generations have trod, have trod, have trod;”\nThe repeated, heavily stressed words chiefly', options: ['speed the line into a light, carefree rhythm', 'signal that the poem has abandoned its beat', 'create a gentle lullaby that soothes the reader', 'imitate the weary, endless tramp of many feet'], correctAnswer: 3, explanation: 'Repeating the stressed word “trod” three times, with pauses between, makes the line plod, so its sound enacts generations tramping over the earth. The crowded stresses slow rather than lighten the line, one emphatic line does not abandon the poem\'s beat, and the weary sound is the opposite of soothing.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 2 },
  { question: 'Read the final line of Alfred, Lord Tennyson\'s “Ulysses” (1842):\n“To strive, to seek, to find, and not to yield.”\nThe line\'s even beat and its pauses at each comma chiefly', options: ['hurry the reader past the verbs toward the poem\'s end', 'give each verb equal weight, building firm resolve', 'break the beat to show the speaker\'s confusion', 'make the line sound casual and conversational'], correctAnswer: 1, explanation: 'The steady, regular beat and the commas give each verb its own stress, so the line marches forward with determination. The pauses slow the reader rather than hurrying, the rhythm is steady rather than broken, and the measured, emphatic verbs are far from casual.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 2 },
  { question: 'Which question about rhythm is the AP English Literature exam most likely to ask about a poem?', options: ['What is the name of the meter used in the first line?', 'How many metrical feet appear in each of the lines?', 'Which syllables would a dictionary mark as stressed?', 'What effect does a change in the beat create there?'], correctAnswer: 3, explanation: 'The exam treats rhythm as a source of effects: it asks what a steady beat or a break in it does at a particular moment. It does not ask students to name a meter or count its feet, and dictionary stress marks say nothing about meaning.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 2 },
  { question: 'Read the opening of Wilfred Owen\'s “Dulce et Decorum Est” (1920):\n“Bent double, like old beggars under sacks,\nKnock-kneed, coughing like hags, we cursed through sludge,”\nThe sounds of these lines are best described as', options: ['smooth, liquid sounds that soften the scene', 'harsh, clustered consonants echoing misery', 'soft sibilance creating a hushed, calm mood', 'exact end rhymes that make the march orderly'], correctAnswer: 1, explanation: 'Hard k, g and d sounds cluster in “Knock-kneed,” “coughing,” “hags” and “sludge,” and this cacophony echoes the soldiers\' exhaustion and filth. The sounds are harsh rather than smooth or hushed, and “sacks” and “sludge” do not rhyme.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 3 },
  { question: 'Read the opening of John Keats\'s “To Autumn” (1820):\n“Season of mists and mellow fruitfulness,\nClose bosom-friend of the maturing sun;”\nThe sound of these lines chiefly supports', options: ['a harsh mood that suits a violent autumn storm', 'an unresolved ending signaled by a near rhyme', 'a ripe, drowsy calm through smooth euphony', 'a noisy scene by imitating the sound of wind'], correctAnswer: 2, explanation: 'Soft m sounds (“mists,” “mellow,” “maturing”) and long, open vowels create euphony that suits the season\'s ripe, unhurried abundance. There are no harsh clusters suggesting violence, these opening lines are not a poem\'s ending, and no word imitates the wind.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 3 },
  { question: 'An elegy uses exact rhymes in every stanza until its final two lines, which pair “gone” with “stone.” The shift to this near rhyme most likely', options: ['shows that the poet could not find a true rhyme', 'signals a cheerful resolution of the speaker\'s grief', 'marks a switch from a closed form to an open form', 'leaves the ending unsettled, like an unhealed loss'], correctAnswer: 3, explanation: 'After a pattern of exact rhymes, a slant rhyme denies the ear the full chime it expects, so the close feels unresolved, which fits grief that has not healed. A late, deliberate change is a choice rather than a failure, a near miss works against cheerful closure, and two final lines do not change the poem\'s form.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 3 },
  { question: 'Read the first line of John Keats\'s sonnet “Bright Star” (written 1819):\n“Bright star, would I were stedfast as thou art—”\nThe speaker\'s direct address to the star is an example of', options: ['apostrophe, which makes the star a silent listener', 'metonymy, which names the sky by a related object', 'synecdoche, which lets one part stand for a whole', 'hyperbole, which exaggerates the star\'s brightness'], correctAnswer: 0, explanation: 'Speaking directly to something absent or nonhuman, here “thou,” the star, is apostrophe; it turns the star into a listener and lets the speaker voice his longing for its constancy. The star is not standing in for something associated with it or for a larger whole, and calling it “bright” is description, not exaggeration.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 4 },
  { question: 'In the sentence “Downing Street refused to comment on the report,” the phrase “Downing Street” is an example of', options: ['metonymy', 'synecdoche', 'apostrophe', 'personification'], correctAnswer: 0, explanation: 'Downing Street is not part of the government but the address associated with the prime minister\'s office, so naming the government by it is metonymy. Synecdoche uses a literal part for the whole, apostrophe is direct address, and personification gives human traits to a nonhuman thing rather than substituting a related name.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 4 },
  { question: 'A poem about a marriage returns again and again to frost on the door latch, a cold hearth and breath clouding in the hallway. Taken together, these images most likely', options: ['celebrate the crisp beauty of a winter morning', 'build a motif of cold that suggests lost warmth', 'form a single symbol of the couple\'s poverty', 'imitate the sound of wind howling outside'], correctAnswer: 1, explanation: 'The images share one quality, cold, and their accumulation forms a motif that points beyond the weather to the emotional chill in the marriage. Nothing in them is celebratory, a recurring pattern of several images is not a single symbol of money, and these are tactile and visual images rather than sounds.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 4 },
  { question: 'Christina Rossetti\'s sonnet “Remember” (1862) opens, “Remember me when I am gone away, / Gone far away into the silent land.” Its ninth line begins, “Yet if you should forget me for a while / And afterwards remember, do not grieve.” The word “Yet” marks', options: ['a turn from asking to be remembered to releasing the beloved from grief', 'a new speaker who answers the first speaker\'s request to be remembered', 'a restatement of the opening request in more urgent and forceful terms', 'an abandonment of the poem\'s subject in favor of a description of nature'], correctAnswer: 0, explanation: 'In a sonnet, line 9 is a common place for the turn, and “Yet” pivots from the plea to be remembered to the wish that the beloved not grieve if memory fades. The same speaker continues, the request is softened rather than intensified, and the subject of memory and loss carries on.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 5 },
  { question: 'Read William Carlos Williams\'s “The Red Wheelbarrow” (1923):\n“so much depends\nupon\n\na red wheel\nbarrow\n\nglazed with rain\nwater\n\nbeside the white\nchickens.”\nThe line breaks that split “wheel / barrow” and “rain / water” chiefly', options: ['slow the reader so each plain object is seen closely', 'mark the predictable rhyme pattern of a closed form', 'show that the poem\'s grammar has broken down', 'hurry the reader past the images toward the end'], correctAnswer: 0, explanation: 'In this open-form poem, line breaks and white space do the shaping: splitting compound words isolates each part, slowing the reader to look at ordinary things with new attention. There is no rhyme pattern, the poem is one grammatical sentence, and the breaks slow rather than hurry the reading.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 5 },
  { question: 'In a poem, one line ends “and then I fell,” and the next line begins “asleep beside the fire.” The line break chiefly', options: ['creates a caesura that slows the middle of the line', 'stops the thought with an end-stopped, complete line', 'raises a brief alarm that the next line turns to calm', 'marks the turn where a sonnet moves to its response'], correctAnswer: 2, explanation: 'Because of the enjambment, “I fell” first reads as a fall or a collapse, and the next line revises it into falling asleep, a small drama of expectation and revision. A caesura is a pause inside a line, the line is not end-stopped because the sentence runs on, and nothing marks a sonnet\'s turn.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 5 },
  { question: 'Robert Browning\'s “My Last Duchess” (1842) begins, “That\'s my last Duchess painted on the wall, / Looking as if she were alive.” The poem is spoken by a duke. A student writes, “Browning admires the painting of his late wife.” What is the main problem with this claim?', options: ['It confuses the poet with the duke who speaks the poem', 'It treats tone as the reader\'s feeling, not the speaker\'s', 'It makes a claim about meaning rather than paraphrasing', 'It analyzes the painting instead of the poem\'s sound'], correctAnswer: 0, explanation: 'The “I” of the poem is a constructed speaker, the duke, not Browning himself, so the claim should be about the speaker. The sentence says nothing about tone versus mood, interpretive claims are the goal rather than a flaw, and a poem\'s subject is a fair thing to analyze.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 6 },
  { question: 'Shakespeare\'s Sonnet 130 (1609) opens, “My mistress\' eyes are nothing like the sun; / Coral is far more red than her lips\' red,” and ends, “And yet, by heaven, I think my love as rare / As any she belied with false compare.” The speaker\'s tone is best described as', options: ['bitterly disappointed in how his beloved looks', 'reverent toward the tradition of flattering praise', 'detached and indifferent toward his beloved', 'playful toward flattery yet sincere about his love'], correctAnswer: 3, explanation: 'The speaker mocks the inflated comparisons of conventional love poetry, then insists in the couplet that his love is as rare as any woman misrepresented by false comparison, so the tone holds playful mockery and sincere affection together. The couplet rules out bitterness and indifference, and the poem pokes fun at the tradition rather than revering it.', difficulty: 'hard', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 6 },
  { question: 'Read the opening of a poem by Emily Dickinson (written in the early 1860s):\n“Much Madness is divinest Sense –\nTo a discerning Eye –\nMuch Sense – the starkest Madness –”\nThese lines are built chiefly on', options: ['situational irony, showing an outcome that nobody expected', 'paradox, which suggests that society mislabels sanity', 'hyperbole, which exaggerates how common madness is', 'verbal irony, which mocks the speaker\'s own madness'], correctAnswer: 1, explanation: 'Calling madness “divinest Sense” and sense “the starkest Madness” is an apparent contradiction that reveals a truth: what the majority calls sane or mad may be backward. No unexpected event occurs, the lines make no claim about how common madness is, and the speaker is not saying the opposite of what she means about herself.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 6 },
  { question: 'In Percy Bysshe Shelley\'s “Ozymandias” (1818), a ruined statue\'s pedestal reads, “My name is Ozymandias, King of Kings; / Look on my Works, ye Mighty, and despair!” The next line is “Nothing beside remains.” Which thesis best combines technique, effect and meaning?', options: ['Shelley uses many devices in this sonnet, including irony, imagery and quotation.', 'The poem describes a traveler who finds a broken statue of a king in the desert.', 'The gap between the boast and the empty desert turns the king\'s pride into irony about power.', 'Shelley wrote the poem because he personally disliked the powerful kings of his day.'], correctAnswer: 2, explanation: 'A complete thesis names a technique (the ironic gap between inscription and ruin), its effect (the boast becomes hollow) and a meaning (power does not last). Listing devices, summarizing the situation and speculating about the poet\'s biography each leave out effect and meaning.', difficulty: 'medium', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 1, part: 7 },
  { question: 'According to a reliable method for close reading an unfamiliar poem, what should a reader do first?', options: ['Label every sound device and figure of speech in the poem', 'Decide on the poem\'s hidden meaning and then find support', 'Paraphrase who speaks, to whom and about what', 'Identify the meter and rhyme scheme of each of its stanzas'], correctAnswer: 2, explanation: 'Interpretation must rest on an accurate literal reading, so the first step is to paraphrase the situation: who speaks, to whom and about what. Labeling devices comes later and only where they do work, deciding on a meaning first invites misreading, and naming meter or rhyme scheme is not what the exam asks.', difficulty: 'easy', domain: 'poetry', topicSlug: 'englit-complex-poetic-analysis', formSet: 2, part: 7 },
]


export function generateExitQuiz(count = 10, topicSlug?: string): { id: string; question: string; options: string[]; correctIndex: number; explanation: string; category: string; partNumber?: number }[] {
  let pool = engLitQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  return shuffleArray(pool).slice(0, count).map((q, i) => ({
    id: `${q.topicSlug}-q${i}`,
    question: q.question,
    options: q.options,
    correctIndex: q.correctAnswer,
    explanation: q.explanation,
    category: q.domain,
    topicSlug: q.topicSlug,
    partNumber: q.part,
  }))
}
